window.TopoCountryStories=[{"id":"steve","lesson":"world-oceania","country":"au","child":"Steve","home":"Sydney","title":"Van mijn haven naar de outback","bounds":[112,-44,155,-10],"places":[{"id":"steve-sydney","name":"Sydney","lon":151.21,"lat":-33.87,"kind":"city"},{"id":"steve-alice","name":"Alice Springs","lon":133.88,"lat":-23.7,"kind":"city"},{"id":"au-cap","name":"Canberra","lon":149.13,"lat":-35.28,"kind":"city"}],"scenes":[{"title":"Mijn stad aan het water","paragraphs":["“Wedden dat ik die boot eerder zie dan jij?” Mijn zusje duwt haar neus bijna tegen het raam. Ik ben Steve en ik woon in Sydney. Vandaag gaan we met mijn vader met de veerboot mee. Op het water varen ook andere boten. Langs de haven staan huizen en hoge gebouwen. Ik vind het leuk dat een gewone tocht zo een klein avontuur wordt.","Op school teken ik Sydney op een kaart van Australië. Mijn stip komt aan de zuidoostkust. “Dus daar zit de regering?” vraagt een klasgenoot. Nee: de hoofdstad is Canberra. Sydney is een grote en bekende stad, maar niet de hoofdstad. Ik zet beide namen op de kaart en kijk welke het dichtst bij de zee ligt.","Vanaf de veerboot wijs ik naar de witte daken van het Opera House. Voor mij lijken ze op zeilen. Het is een theatergebouw aan de haven, geopend in 1973. “Dus dat is geen heel oud kasteel?” vraagt mijn zusje. Nee! Ook een vrij nieuw gebouw kan belangrijk erfgoed zijn. Ik teken een klein zeil naast Sydney. Zo onthoud ik mijn stad aan het water, terwijl de rode grond op het kaartje van mijn oom me aan het verre binnenland laat denken."],"points":["steve-sydney","au-cap"],"question":"Waar woont Steve?","options":["steve-sydney","au-cap"],"answer":"steve-sydney","explanation":"Steve woont in Sydney, aan de zuidoostkust van Australië. Canberra is de hoofdstad.","learn":"Een kuststad ligt bij zee. Een bekende of grote stad hoeft niet de hoofdstad te zijn.","kind":"map"},{"title":"Mijn oom woont niet om de hoek","paragraphs":["Mijn oom stuurt een foto van rode grond en een wijde lucht. Hij woont bij Alice Springs, ver in het binnenland. Dat gebied hoort bij de outback: een naam voor grote, afgelegen delen van Australië. “Kunnen we na school bij hem langs?” vraagt mijn zusje. Ik moet lachen. Op ons tabletscherm staan onze stippen niet eens zo ver uit elkaar. In het echt is het een enorme afstand.","Ik trek op de kaart een denkbeeldige rechte lijn van Sydney naar Alice Springs. Die vertelt niet welke wegen je kunt volgen. We zouden eerst moeten uitzoeken hoe we erheen reizen. Als ik bij mijn oom logeer, maakt hij graag een wandeling met me. Op een warme middag zoeken we daarna de schaduw op. Voor een bezoek aan familie verderop plannen we de reis samen: buiten de stad kunnen de afstanden groot zijn. Bij mij thuis is de volgende winkel vaak veel dichterbij."],"points":["steve-sydney","steve-alice"],"question":"Welke plek uit het verhaal ligt ver van de kust in het binnenland?","options":["steve-sydney","steve-alice"],"answer":"steve-alice","explanation":"Alice Springs ligt in het binnenland, ver van Sydney. Een korte lijn op het scherm kan een grote echte afstand voorstellen.","learn":"Outback is een ruime gebiedsnaam, geen stad met één precieze grens. Een rechte lijn is geen routebeschrijving.","kind":"map"},{"title":"Eén land, verschillende landschappen","paragraphs":["De bal rolt onder het tuinbankje. Mijn zusje kruipt erachteraan terwijl ik mijn oom bel. Bij ons in Sydney zijn er wolken boven de haven. Hij vertelt dat hij vandaag juist een droge wandeling maakte. “Dus bij jou regent het nooit?” vraag ik. Hij schudt zijn hoofd. Eén dag vertelt niet hoe het er altijd is. Het weer gaat over nu; voor het klimaat kijk je naar een lange tijd.","Op een klimaatkaart zie ik dat Australië niet overal hetzelfde is. Rond Alice Springs is het droog, maar er zijn ook tropische en gematigde gebieden. Ik wil twee foto’s naast elkaar leggen: mijn haven en het landschap bij mijn oom. “Welke foto is het echte Australië?” vraagt mijn zusje. “Allebei”, zeg ik. “Maar ze laten nog lang niet het hele land zien.”"],"points":["steve-sydney","steve-alice","au-cap"],"question":"Wat heb je nodig om het klimaat van Sydney en Alice Springs te vergelijken?","options":["Temperatuur en neerslag over een lange tijd","De weersverwachting voor morgen in beide steden","Eén foto van een droge dag in beide steden"],"answer":0,"explanation":"Klimaat beschrijft patronen over een lange tijd. Eén regenachtige of droge dag is daarvoor niet genoeg.","learn":"Geografisch onderzoeken: vergelijk een kaart, foto’s en klimaatgegevens. Één ervaring is niet het hele land.","kind":"choice"}],"sources":[{"title":"Bureau of Meteorology · klimaatgebieden","url":"https://www.bom.gov.au/resources/learn-and-explore/climate-knowledge-centre/australian-climate-zones"},{"title":"Tourism Australia · Sydney en Alice Springs","url":"https://www.australia.com/en-gb/trips-and-itineraries/sydney-and-surrounds/ultimate-trip-to-australia.html"},{"title":"UNESCO · natuur en erfgoed bij dit verhaal","url":"https://whc.unesco.org/en/list/166/"}],"version":"59e151bcdabd","memory_cue":"Sydney: haven en Opera House; Alice Springs: ver in het binnenland.","insight":{"version":1,"question":"Waarom helpt Steves zeiltekening om Sydney te onthouden?","options":["Het beeld verbindt een herkenbaar gebouw met de havenligging","De tekening laat zien dat Sydney de hoofdstad is","Het gebouw ligt midden in de outback"],"answer":0,"explanation":"Het Opera House staat aan de haven van Sydney. Het beeld helpt bij de ligging; Canberra blijft de hoofdstad."}},{"id":"lena","lesson":"eu-buren","country":"de","child":"Lena","home":"Berlijn","title":"Een rivier tussen mijn straten","bounds":[5,47,16,55.5],"places":[{"id":"de-cap","name":"Berlijn","lon":13.4,"lat":52.52,"kind":"city"},{"id":"lena-hamburg","name":"Hamburg","lon":9.99,"lat":53.55,"kind":"city"},{"id":"rhine","name":"Rijn","lon":7.6,"lat":50.35,"kind":"river"}],"scenes":[{"title":"De brug bij mijn buurt","paragraphs":["Ik ben Lena en ik woon in Berlijn. Mijn vriend zegt dat een stad vooral uit straten bestaat. Ik neem hem mee naar een brug. Onder ons vaart een boot over de Spree. Aan de overkant lopen mensen langs het water. “Een rivier is hier dus óók een soort verbinding”, zegt hij. Precies. Om bij de andere oever te komen, hebben wij juist een brug nodig.","Thuis zoek ik Berlijn op de kaart. De stad ligt in Duitsland en is ook de hoofdstad. Dat maakt niet iedere straat bijzonder: ik moet nog steeds mijn tas zoeken en op tijd op school komen. Op mijn eigen buurtkaart teken ik eerst de plekken waar ik vaak ben. Op de landenkaart zet ik maar één stip voor heel Berlijn.","Op een wandeling wijst mijn vader naar het Museumeiland. “Een eiland midden in Berlijn?” vraag ik. Ja: tussen water liggen vijf museumgebouwen, gebouwd in de negentiende en twintigste eeuw. Mensen bewaren er kunst en voorwerpen om het verleden te onderzoeken. De rivier is dus niet alleen een blauwe lijn naast onze straten. Hij helpt ook om bijzondere plekken in de stad terug te vinden. Ik teken een klein museum naast het water op mijn eigen kaartje."],"points":["de-cap","lena-hamburg"],"question":"In welke stad woont Lena?","options":["de-cap","lena-hamburg"],"answer":"de-cap","explanation":"Lena woont in Berlijn, de hoofdstad van Duitsland. Op een landenkaart wordt de hele stad sterk verkleind.","learn":"Een kaart op buurtniveau laat andere details zien dan een kaart van een heel land.","kind":"map"},{"title":"Een pakketje uit Hamburg","paragraphs":["Mijn tante in Hamburg stuurt een pakketje. In de doos zit ook een tekening van een groot schip. Ze vertelt over de haven. Ik zet Hamburg en Berlijn op dezelfde kaart. Hamburg ligt noordelijker dan mijn woonplaats. Een schip kan niet zomaar over iedere straat varen. Voor vervoer zijn waterwegen, wegen en spoorlijnen belangrijk.","Ik wil weten hoe mijn pakketje precies bij ons kwam. De kaart geeft mogelijkheden, maar geen bewijs van zijn hele reis. Misschien ging het een stuk met een vrachtwagen. Daarvoor zou ik informatie van de vervoerder nodig hebben. Mijn vriend tekent voor de grap een schip op onze straat. “Dat zou nogal krap worden”, zeg ik."],"points":["de-cap","lena-hamburg"],"question":"Wat kun je wél met alleen deze kaart onderzoeken?","options":["Of Hamburg noordelijker ligt dan Berlijn","Welke route dit ene pakketje precies heeft afgelegd","Hoe lang de bezorger over deze reis deed"],"answer":0,"explanation":"De kaart toont ligging. Voor de echte reis van één pakketje heb je andere informatie nodig.","learn":"Ligging is iets anders dan een bewezen route. Vervoer verbindt plaatsen.","kind":"choice"},{"title":"De Rijn is niet de Spree","paragraphs":["Op school laat iemand een foto van de Rijn zien. “Die rivier loopt dus ook onder jouw brug!” zegt mijn vriend. Nu mag ik hem verbeteren: bij onze brug stroomt de Spree. De Rijn ligt veel verder naar het westen. Ik zoek de naam op een kaart met rivieren. Niet alle blauwe lijnen stellen hetzelfde water voor.","We maken een onderzoeksvraag: waarom vind je langs rivieren steden, bruggen en havens? Het water kan handig zijn voor vervoer en voor mensen die ergens wonen of werken. Maar hoog water kan ook problemen geven. Een rivier is dus meer dan een lijn om uit je hoofd te leren. Toch helpt die naam op de kaart me om te begrijpen over welke plek het gaat."],"points":["de-cap","rhine"],"question":"Waarom is een kaart met riviernamen hier nuttig?","options":["Je kunt de Rijn en de Spree uit elkaar houden","Je kunt zonder andere bron de waterstand van vandaag aflezen","Je weet meteen hoe lang iedere boot onderweg is"],"answer":0,"explanation":"Een kaart met namen helpt verschillende rivieren en hun ligging te herkennen.","learn":"Water kan een verbinding zijn én een risico vormen. Topografische namen helpen om zulke verbanden te bespreken.","kind":"choice"}],"sources":[{"title":"Stad Berlijn · rivieren","url":"https://www.berlin.de/en/tourism/rivercruises-boattrips/"},{"title":"UNESCO · natuur en erfgoed bij dit verhaal","url":"https://whc.unesco.org/en/list/896/"}],"version":"9350befc8737","memory_cue":"Berlijn: stad aan de Spree, met een Museumeiland.","insight":{"version":1,"question":"Wat verbindt het Museumeiland met aardrijkskunde én geschiedenis?","options":["De ligging tussen water en het bewaren van voorwerpen uit het verleden","Alle Duitse steden liggen op hetzelfde eiland","Een museum vertelt hoe laat de trein vertrekt"],"answer":0,"explanation":"Je onderzoekt zowel waar een plek ligt als wat mensen er uit het verleden bewaren."}},{"id":"ines","lesson":"eu-west","country":"fr","child":"Inès","home":"Lyon","title":"Twee rivieren en één logeerkaart","bounds":[-5,42,9,51.5],"places":[{"id":"ines-lyon","name":"Lyon","lon":4.84,"lat":45.76,"kind":"city"},{"id":"fr-cap","name":"Parijs","lon":2.35,"lat":48.86,"kind":"city"},{"id":"alps","name":"Alpen","lon":6.8,"lat":45.8,"kind":"area"}],"scenes":[{"title":"Mijn stad heeft twee rivieren","paragraphs":["Ik ben Inès en ik woon in Lyon. Als ik een tekening van mijn stad maak, teken ik twee blauwe lijnen. Dat zijn de Rhône en de Saône. Verderop komen ze samen. Mijn broertje maakt er een blauwe spaghetti van. “Dan weet niemand meer aan welke kant de brug ligt”, zeg ik. We moeten wel goed blijven kijken.","Op een buurtkaart zie ik straten en bruggen. Op de kaart van Frankrijk wordt Lyon één stip. Parijs ligt veel noordelijker en is de hoofdstad. Ik ben daar weleens geweest, maar mijn gewone dagen spelen zich in Lyon af: school, mijn vrienden en de plek waar we graag buiten zijn. Frankrijk is voor mij dus meer dan alleen Parijs.","Mijn oma laat een foto zien van oude huizen in Lyon. In sommige buurten werkten vroeger zijdewevers: zij maakten stof van zijdedraad. De stad groeide door handel en werk, niet alleen doordat iemand er een mooie stip op een kaart zette. De Rhône en de Saône helpen me om Lyon terug te vinden. Ik stel me twee blauwe linten naast oude werkplaatsen voor. Op straat zie ik nu ook scholen en winkels: een stad blijft veranderen, terwijl delen van het verleden zichtbaar blijven."],"points":["ines-lyon","fr-cap"],"question":"Waar woont Inès?","options":["fr-cap","ines-lyon"],"answer":"ines-lyon","explanation":"Inès woont in Lyon. Parijs is de hoofdstad, maar niet de woonplaats van ieder Frans kind.","learn":"Een hoofdstad vertelt niet hoe iedereen in een land woont. Rivieren kunnen een stad mede vormgeven.","kind":"map"},{"title":"Een kaart voor de logeerreis","paragraphs":["Voor een logeerbezoek in Parijs wil ik zelf de reis voorbereiden. Op de landenkaart lijken onze stippen dichtbij. Mijn moeder vraagt welke kaart ik nodig heb om een trein te vinden. Ik wijs eerst de gewone kaart aan, maar daar staan niet alle spoorlijnen op. We zoeken een verbindingenkaart erbij.","Op het scherm kunnen we de twee steden met een rechte lijn verbinden. Een echte trein volgt het spoor en stopt misschien onderweg. De reistijd kunnen we dus niet uit dat ene lijntje aflezen. Ik maak drie vakjes in mijn schrift: waar liggen de steden, welke verbinding is er, en welke vertrektijd hoort erbij? Voor elke vraag gebruik ik passende informatie."],"points":["ines-lyon","fr-cap"],"question":"Welke extra bron helpt bij het plannen van een treinreis?","options":["Een spoor- of verbindingenkaart","Een kaart die alleen landsgrenzen toont","Een lijst met hoogtes zonder spoorlijnen"],"answer":0,"explanation":"Een verbindingenkaart laat spoorlijnen zien; voor tijden gebruik je een actuele reisplanner.","learn":"Kies een bron die bij je vraag past. Hemelsbreed is niet hetzelfde als de echte route.","kind":"choice"},{"title":"Verderop veranderen de vormen","paragraphs":["Als we vanuit Lyon naar het oosten reizen, komen we richting de Alpen. Op een hoogtekaart krijgen de kleuren daar een andere betekenis dan op mijn buurtkaart. Ik zoek de legenda. Bruin betekent hier niet dat de grond overal bruin is, maar helpt hoogte te tonen.","Ik leg een foto van bergen naast een foto van onze rivieroever. Het zijn heel andere plekken, allebei in of bij mijn deel van Frankrijk. In de bergen kunnen hellingen en dalen invloed hebben op waar wegen en huizen liggen. Ik zou graag ontdekken hoe een kind daar naar school gaat. Maar dat moet ik vragen, niet zomaar uit een bergfoto verzinnen."],"points":["ines-lyon","alps"],"question":"Wat moet je eerst bekijken als je hoogtekleuren wilt begrijpen?","options":["De legenda van die kaart","De kleuren van een andere kaart zonder de legenda te lezen","Alleen de plaatsnamen op de kaart"],"answer":0,"explanation":"De legenda vertelt wat kleuren op juist deze kaart betekenen.","learn":"Landschap beïnvloedt mogelijkheden voor wonen en vervoer. Een foto vertelt niet automatisch hoe iedereen leeft.","kind":"choice"}],"sources":[{"title":"Lyon Métropole · Rhône en Saône","url":"https://www.grandlyon.com/mes-services-au-quotidien/sinformer-sur-les-projets-urbains-dans-la-metropole/lyon-confluence"},{"title":"UNESCO · natuur en erfgoed bij dit verhaal","url":"https://whc.unesco.org/en/list/872/"}],"version":"ffbf2852480a","memory_cue":"Lyon: twee rivieren, oude handelsstad en zijdewevers.","insight":{"version":1,"question":"Welke combinatie helpt de ontwikkeling van Lyon te begrijpen?","options":["De ligging bij rivieren en de geschiedenis van handel en werk","Alleen de letters van de plaatsnaam","De aanname dat iedere inwoner nog zijde weeft"],"answer":0,"explanation":"Ligging, handel en werk hangen samen. Een historische bedrijfstak beschrijft niet het werk van alle huidige bewoners."}},{"id":"maja","lesson":"eu-noord","country":"no","child":"Maja","home":"Bergen","title":"Een bocht langs het water","bounds":[3,57,16,64],"places":[{"id":"maja-bergen","name":"Bergen","lon":5.32,"lat":60.39,"kind":"city"},{"id":"no-cap","name":"Oslo","lon":10.75,"lat":59.91,"kind":"city"},{"id":"maja-fjord","name":"Sognefjord","lon":6.8,"lat":61.1,"kind":"water"}],"scenes":[{"title":"Een jas bij de deur","paragraphs":["Ik ben Maja en ik woon in Bergen, aan de westkust van Noorwegen. Voor ik wegga, kijk ik naar de lucht en zoek ik mijn jas. Dat doe ik niet omdat het hier altijd hetzelfde weer is, maar juist omdat ik wil weten hoe het vandaag is. Bij de haven kijk ik soms naar de boten. In mijn stad zijn ook scholen, winkels en drukke straten.","Op de kaart zoek ik Bergen. Daarna zoek ik Oslo, de hoofdstad. Die ligt verder naar het oosten. Een foto van één boot vertelt nog niet waar je in Noorwegen bent. Daarom schrijf ik de plaatsnaam bij mijn foto. Zo kan iemand anders de plek ook op een kaart terugvinden."],"points":["maja-bergen","no-cap"],"question":"Welke stad ligt volgens de kaart verder naar het oosten?","options":["maja-bergen","no-cap"],"answer":"no-cap","explanation":"Oslo ligt oostelijker dan Bergen. Op deze kaart staat oost rechts.","learn":"Een foto met een plaatsnaam is gemakkelijker geografisch te plaatsen dan een foto zonder locatie.","kind":"map"},{"title":"Het water loopt het land in","paragraphs":["Mijn familie maakt een uitstap richting een fjord. Dat is een lange, smalle zeearm die het land in loopt. Bij een kaart van de Sognefjord volg ik met mijn vinger alle bochten. Mijn neef trekt een rechte lijn naar de overkant. “Klaar, daar gaan we!” zegt hij. Zo eenvoudig is de echte reis niet.","Water en steile hellingen kunnen bepalen waar je kunt rijden of lopen. Soms zijn er bruggen, tunnels of veerboten. Welke je gebruikt, moet je op een geschikte kaart en bij de vervoerder controleren. Ik vind het grappig: op een lege kaart is mijn potlood veel sneller dan wij in het echt.","“Heeft iemand die diepe dalen uitgegraven?” vraagt mijn broertje bij een foto van een fjord. Lang geleden schuurde bewegend gletsjerijs dalen uit. Later kwam er zeewater in. Daarom kan een fjord diep en steil zijn. Dat helpt me om de bochtige westkust van Noorwegen te begrijpen. Voor mensen kan het water een vaarweg zijn, maar voor een autorit juist een omweg betekenen. Ik teken een ijsblokje bij het dal: zo horen het landschap van vroeger en onze reis van vandaag bij elkaar."],"points":["maja-bergen","maja-fjord"],"question":"Waarom kan een rechte lijn op de kaart een onbruikbare reisroute zijn?","options":["Er kan water of steil landschap tussen liggen","De kortste lijn is altijd een bestaande weg","De echte route hangt alleen af van het begin- en eindpunt"],"answer":0,"explanation":"Een echte route moet passen bij water, hellingen en bestaande verbindingen.","learn":"Een fjord is zeewater dat ver het land in reikt. Ligging en landschap hebben invloed op vervoer.","kind":"choice"},{"title":"Niet heel Noorwegen is mijn straat","paragraphs":["In de klas vergelijken we een foto van Bergen met beelden van een dorp verder naar het noorden. Ik herken niet alles. De juf vraagt of ik als Noorweegs kind precies weet hoe het daar dagelijks is. Nee dus. Ik kan over mijn eigen buurt vertellen, maar moet voor die andere plek ook iets opzoeken.","We gebruiken een kaart voor de ligging en verhalen voor ervaringen. Wie wil weten hoe lang het licht is, moet bovendien naar de plaats én het seizoen kijken. Ik schrijf onder mijn fotoblad: dit is mijn Bergen. Het is een stukje van Noorwegen, niet het hele verhaal van iedereen."],"points":["maja-bergen","no-cap"],"question":"Kun je uit Maja’s buurtverhaal afleiden hoe ieder Noors kind leeft?","options":["Nee, je hebt ook andere voorbeelden en bronnen nodig","Ja, want haar stad en het dorp liggen in hetzelfde land","Ja, de ligging van de hoofdstad vertelt genoeg over alle dorpen"],"answer":0,"explanation":"Eén persoonlijk verhaal laat één perspectief zien. Vergelijk meerdere plekken en bronnen.","learn":"Een persoonlijk perspectief maakt een plek levendig, maar is geen beschrijving van alle bewoners.","kind":"choice"}],"sources":[{"title":"Visit Bergen · westkust en fjorden","url":"https://en.visitbergen.com/things-to-do/norway-fjords/bergen-the-gateway-to-the-fjords-of-norway"},{"title":"UNESCO · natuur en erfgoed bij dit verhaal","url":"https://whc.unesco.org/en/list/1195/"}],"version":"262f18f045a7","memory_cue":"Noorse westkust: gletsjerdalen met zeewater; varen of omrijden.","insight":{"version":1,"question":"Waarom verbindt een fjord natuurgeschiedenis met vervoer?","options":["IJs vormde het dal en het zeewater beïnvloedt de routes van nu","Een fjord is een door mensen gegraven treinspoor","Elke rechte lijn over een fjord is een autoweg"],"answer":0,"explanation":"Gletsjerijs vormde dalen. Nadat zeewater erin kwam, moesten mensen hun verbindingen daarop aanpassen."}},{"id":"luca","lesson":"eu-zuidwest","country":"it","child":"Luca","home":"Napels","title":"De berg op mijn tekening","bounds":[6,36,19,48],"places":[{"id":"luca-naples","name":"Napels","lon":14.27,"lat":40.85,"kind":"city"},{"id":"it-cap","name":"Rome","lon":12.5,"lat":41.9,"kind":"city"},{"id":"luca-vesuvius","name":"Vesuvius","lon":14.43,"lat":40.82,"kind":"area"}],"scenes":[{"title":"Mijn uitzicht heeft een naam","paragraphs":["Ik ben Luca en ik woon in Napels. Op mijn tekening van de omgeving staat ook de Vesuvius. “Is dat gewoon een hoge heuvel?” vraagt een vriend. We zoeken het samen op: de Vesuvius is een vulkaan. Ik wil geen spannende verhalen verzinnen over wat er morgen gebeurt. Daarvoor zijn echte metingen en deskundigen nodig.","Op de kaart zie ik Napels aan de kust in Italië. Verder naar het noordwesten ligt Rome, de hoofdstad. Mijn eigen straat is op deze grote kaart niet zichtbaar. Toch helpt de stip Napels me om uit te leggen waar mijn gewone leven zich afspeelt. Een stad is zoveel meer dan haar bekendste uitzicht."],"points":["luca-naples","it-cap","luca-vesuvius"],"question":"In welke stad woont Luca?","options":["it-cap","luca-naples","luca-vesuvius"],"answer":"luca-naples","explanation":"Luca woont in Napels. Rome is de hoofdstad; de Vesuvius is een vulkaan.","learn":"Een stad, een hoofdstad en een vulkaan zijn verschillende soorten geografische objecten.","kind":"map"},{"title":"Een berg of een waarschuwing?","paragraphs":["Voor een schoolopdracht bekijk ik een gewone kaart en informatie over de vulkaan. Op de kaart kan ik de ligging zien. Maar die vertelt niet of er op dit moment iets verandert in de vulkaan. Wetenschappers volgen daarvoor onder meer metingen. We kijken met de leerkracht welke bron bij onze vraag past.","Mijn vriend wil van één foto aflezen of een vulkaan veilig is. Ik vraag hem of je aan een foto van onze school ook precies kunt zien wat er morgen gebeurt. We besluiten verschillende vragen uit elkaar te houden: waar ligt de plek, hoe werkt een vulkaan en wat zeggen de bevoegde deskundigen over de actuele situatie?","Op school bekijken we resten van Pompeï, bij de Vesuvius. In het jaar 79 bedekte een uitbarsting de Romeinse stad met vulkanisch materiaal. Archeologen onderzoeken er huizen en voorwerpen om meer over het leven van toen te leren. Ik vind het vreemd: een berg die nu rustig op de kaart staat, heeft de omgeving enorm veranderd. Mijn geheugensteuntje wordt Napels, vulkaan, oude stad. Het is geen voorspelling van een nieuwe uitbarsting; daarvoor zijn metingen en waarschuwingen van deskundigen nodig."],"points":["luca-naples","luca-vesuvius"],"question":"Welke vraag beantwoordt een gewone topografische kaart het best?","options":["Waar de Vesuvius ligt","Hoe groot het risico morgen precies is","Welke weg op dit moment veilig is"],"answer":0,"explanation":"De kaart helpt bij ligging. Voor actuele vulkaaninformatie zijn deskundige metingen nodig.","learn":"Topografie helpt een natuurverschijnsel te plaatsen. Actuele risico’s vragen om andere bronnen.","kind":"choice"},{"title":"Mijn Italië is niet overal hetzelfde","paragraphs":["Ik stuur mijn neef in Rome mijn tekening. Hij stuurt er een van zijn buurt terug. We wonen in hetzelfde land, maar onze uitzichten zijn niet hetzelfde. In een atlas zien we ook hoge bergen in Noord-Italië en lange stukken kust. De vorm van de laars is handig om Italië te herkennen, maar vertelt nog niet hoe het overal is.","Ik schrijf een vraag bij mijn tekening: welke invloed heeft het landschap op jouw woonplek? Mijn neef tekent een brug. Ik teken de kust en de vulkaan. Daarna willen we uitzoeken waarom mensen juist op die plekken wonen. We merken hoeveel vragen er achter één stip op de kaart schuilgaan."],"points":["luca-naples","it-cap"],"question":"Welke onderzoeksvraag verbindt landschap met het leven van mensen?","options":["Hoe heeft het landschap invloed op wonen en vervoer?","Hoe spel je de naam van de hoofdstad?","Hoeveel letters heeft de naam van het land?"],"answer":0,"explanation":"Aardrijkskunde onderzoekt onder meer verbanden tussen landschap, mensen en ruimte.","learn":"De kaartnaam is een beginpunt om verbanden te onderzoeken, geen eindpunt van het leren.","kind":"choice"}],"sources":[{"title":"INGV · informatie en monitoring Vesuvius","url":"https://www.ov.ingv.it/index.php/monitoraggio-sismico-e-vulcanico/vesuvio/obiettivo-vesuvio"},{"title":"UNESCO · natuur en erfgoed bij dit verhaal","url":"https://whc.unesco.org/en/list/829/"}],"version":"2d98cece7ce4","memory_cue":"Napels en omgeving: Vesuvius en de Romeinse resten van Pompeï.","insight":{"version":1,"question":"Wat kun je met de resten van Pompeï onderzoeken?","options":["Hoe mensen in een Romeinse stad leefden vóór de uitbarsting","Op welke dag de Vesuvius opnieuw zal uitbarsten","Waarom alle Italiaanse steden identiek zijn"],"answer":0,"explanation":"Huizen en voorwerpen zijn historische bronnen. Ze voorspellen geen actuele vulkaanuitbarsting."}},{"id":"amina","lesson":"world-africa","country":"ke","child":"Amina","home":"Nairobi","title":"Van mijn stad naar de kust","bounds":[33,-5,44,5],"places":[{"id":"ke-cap","name":"Nairobi","lon":36.82,"lat":-1.29,"kind":"city"},{"id":"amina-mombasa","name":"Mombasa","lon":39.67,"lat":-4.05,"kind":"city"},{"id":"indian","name":"Indische Oceaan","lon":43,"lat":-4,"kind":"water"}],"scenes":[{"title":"Mijn gewone schooldag","paragraphs":["Ik ben Amina en ik woon in Nairobi, de hoofdstad van Kenia. In mijn tas zitten schoolspullen en een boek dat ik nog wil uitlezen. Onderweg zie ik mensen naar hun werk gaan. Mijn vriendin wil na school afspreken. Mijn vriendin en ik bespreken onderweg welk spel we later gaan doen. Soms praten we zo druk dat ik bijna vergeet welke bladzijde we moesten lezen. Thuis begint voor mij bij de straat en de mensen die ik ken.","Op een kaart van Afrika is Nairobi maar een kleine stip. Kenia is één van de vele landen van het werelddeel. Op een kaart van mijn buurt zie je juist veel meer details. Voor een vriend in een ander land zou ik eerst Kenia aanwijzen, daarna Nairobi en dan pas uitleggen hoe mijn eigen omgeving eruitziet."],"points":["ke-cap","amina-mombasa"],"question":"In welke stad woont Amina?","options":["amina-mombasa","ke-cap"],"answer":"ke-cap","explanation":"Amina woont in Nairobi, de hoofdstad van Kenia.","learn":"Een werelddeel, een land, een stad en een buurt zijn verschillende ruimtelijke niveaus.","kind":"map"},{"title":"Een kaartje van mijn tante","paragraphs":["Mijn tante in Mombasa stuurt een kaartje met water op de voorkant. Ze woont aan de kust. Ik zoek Mombasa op en zie de Indische Oceaan. Mijn woonplaats Nairobi ligt in het binnenland. Alleen doordat we in hetzelfde land wonen, liggen onze huizen nog niet om de hoek.","Ik wil graag weten hoe haar buurt eruitziet. Op de kaart kan ik haar kustligging herkennen. Om de straat te zien heb ik een foto of een beschrijving nodig. Mijn tante vraagt terug welke plek ik in Nairobi het fijnst vind. Daar hoef ik geen atlas voor open te slaan: dat gaat over mijn eigen ervaring."],"points":["ke-cap","amina-mombasa","indian"],"question":"Welke stad uit het verhaal ligt aan de kust?","options":["ke-cap","amina-mombasa"],"answer":"amina-mombasa","explanation":"Mombasa ligt aan de Indische Oceaan; Nairobi ligt in het binnenland.","learn":"Kust en binnenland kunnen verschillen in landschap en verbindingen. Een kaart en een persoonlijk verhaal vullen elkaar aan.","kind":"map"},{"title":"Meer dan één foto","paragraphs":["Voor een werkstuk zoekt iemand één dierenfoto en zet erboven: zo is Kenia. Ik vind de dieren interessant, maar mis mijn stad op het blad. Mijn tante zou haar haven missen. We zoeken daarom ook beelden van straten, water en andere landschappen. Niet om één foto fout te noemen, maar om het verhaal groter te maken.","Ik voeg een stukje over mijn schooldag toe. Dat is ook geen verhaal van ieder kind in Kenia. Het is dat van mij. We schrijven bij elke foto waar die is gemaakt en welke vraag ze helpt beantwoorden. Dan kan de lezer beter begrijpen wat we wel en niet weten.","Een klasgenoot tekent heel Kenia als één warme vlakte. Onze juf laat Mount Kenya zien: een hoge berg bij de evenaar, met andere begroeiing op verschillende hoogtes. “Bij de evenaar is het toch overal even warm?” vraag ik. Nee: hoogte maakt ook verschil. We zoeken eerst Nairobi op en kijken daarna naar de berg verder naar het noorden. Zo onthoud ik dat één land steden, kust en hoge bergen kan hebben. Mijn schooldag vertelt één verhaal; het landschap biedt nog veel meer verhalen."],"points":["ke-cap","amina-mombasa"],"question":"Waarom gebruiken de kinderen meer dan één foto en verhaal?","options":["Om verschillende plekken en ervaringen te laten zien","Omdat een landschapsfoto vanzelf ook het leven in alle steden toont","Om iedereen in het land dezelfde ervaring toe te schrijven"],"answer":0,"explanation":"Eén beeld of ervaring is geen volledige beschrijving van een heel land.","learn":"Vergelijk bronnen en perspectieven. Leer een land kennen zonder het tot één landschap of één levenswijze te beperken.","kind":"choice"}],"sources":[{"title":"Kenya Tourism Board · Kenia","url":"https://magicalkenya.com/"},{"title":"UNESCO · natuur en erfgoed bij dit verhaal","url":"https://whc.unesco.org/en/list/800/"}],"version":"8879b0b44072","memory_cue":"Kenia: Nairobi in het binnenland, Mombasa aan zee, hoge bergen bij de evenaar.","insight":{"version":1,"question":"Waarom is één warme vlakte geen goede beschrijving van heel Kenia?","options":["Er zijn verschillende landschappen en hoogte maakt verschil","Bij de evenaar kunnen geen bergen liggen","Alle plaatsen hebben hetzelfde weer als Nairobi"],"answer":0,"explanation":"Mount Kenya laat zien dat hoogte en landschap verschillen binnen een land. Eén beeld is onvoldoende."}},{"id":"haru","lesson":"world-asia","country":"jp","child":"Haru","home":"Yokohama","title":"Mijn trein en de berg in de verte","bounds":[130,31,142,39],"places":[{"id":"haru-yokohama","name":"Yokohama","lon":139.64,"lat":35.44,"kind":"city"},{"id":"jp-cap","name":"Tokio","lon":139.69,"lat":35.68,"kind":"city"},{"id":"haru-fuji","name":"Fuji","lon":138.73,"lat":35.36,"kind":"area"}],"scenes":[{"title":"De stippen liggen dicht bij elkaar","paragraphs":["Ik ben Haru en ik woon in Yokohama. Als we met de trein naar Tokio gaan, moet ik goed naar de stationsnamen kijken. Op een wereldkaart liggen de twee steden bijna op elkaar. Toch zijn het verschillende steden, met veel straten en buurten. In een atlas zoek ik Tokio als hoofdstad van Japan. Daarna zoek ik mijn eigen woonplaats.","Mijn vriend wil de afstand met zijn vinger meten. Maar zijn kaart is veel kleiner dan die van mij. We kunnen die vingers dus niet zomaar vergelijken. Eerst moeten we weten welke echte afstand een stukje op elke kaart voorstelt. Zo ontdekken we waarom de schaal belangrijk is."],"points":["haru-yokohama","jp-cap"],"question":"Wat helpt om afstanden op twee verschillende kaarten te vergelijken?","options":["De schaal van beide kaarten","Alleen de grootte van het scherm","Alleen de grootte van de stadssymbolen"],"answer":0,"explanation":"De schaal koppelt een afstand op de kaart aan een echte afstand.","learn":"Dichtbij op een wereldkaart kan in het echt nog een flinke afstand zijn. Kijk naar de schaal.","kind":"choice"},{"title":"Soms zie ik een berg","paragraphs":["Op een heldere dag zoeken we vanaf een geschikte uitkijkplek naar de Fuji. Soms zitten er wolken voor en zien we niets. Dat betekent niet dat de berg is verdwenen. Ik moet lachen om mijn vriend, die zegt dat we dan gewoon een berg kunnen bijtekenen. Voor een tekening mag dat; voor een aardrijkskundig onderzoek moeten we wel eerlijk blijven.","Op de kaart zie ik dat de Fuji westelijker ligt dan Yokohama en Tokio. De bergen en de steden laten verschillende kanten van Japan zien. Een bergfoto vertelt iets over die plek en dat moment, maar niet vanzelf hoe het dagelijks leven in mijn straat is.","In een boek zie ik een prent van de Fuji. Die berg staat al eeuwen op schilderijen en in gedichten. Sommige mensen geven de berg ook een religieuze betekenis. Mijn oom tekent hem om de vorm te onthouden; een ander denkt aan een wandeling. Dezelfde plek kan dus iets anders voor mensen betekenen. Ik zet de naam bij het kaartanker, niet zomaar bij een mooie foto. Zo verbind ik een herkenbare berg in Japan met natuur, kunst en de ligging ten westen van onze omgeving."],"points":["haru-yokohama","jp-cap","haru-fuji"],"question":"Welk kaartanker ligt het verst naar het westen?","options":["jp-cap","haru-yokohama","haru-fuji"],"answer":"haru-fuji","explanation":"De Fuji ligt westelijker dan de twee steden. Op deze kaart staat west links.","learn":"Gebruik de echte kaartankers en hun verwijslijnen. Een label kan voor de leesbaarheid iets zijn verschoven.","kind":"map"},{"title":"Ruimte delen","paragraphs":["Voor een schoolopdracht kijken we naar een stad en het berglandschap daarbuiten. In een stad moeten mensen ruimte vinden voor huizen, scholen, parken, wegen en spoor. In berggebieden kunnen steile hellingen het bouwen en reizen moeilijker maken. Daarom wil ik op de kaart niet alleen plaatsnamen, maar ook hoogte en verbindingen zien.","Ik teken mijn ideale buurt met een station en een park. Mijn vriend wil eerst een voetbalveld. We moeten kiezen hoe we de ruimte gebruiken. Er is niet op iedere plek plaats voor alles. Dat vind ik een veel lastiger vraag dan alleen een stad opzoeken, maar ook een leukere om samen over te praten."],"points":["haru-yokohama","jp-cap","haru-fuji"],"question":"Welke twee kaartlagen helpen om landschap en vervoer samen te onderzoeken?","options":["Hoogte en spoorwegen","Alleen landsgrenzen en vlaggen","Alleen hoofdsteden en hun namen"],"answer":0,"explanation":"Met hoogte en verbindingen kun je onderzoeken waar reizen of bouwen gemakkelijker of lastiger kan zijn.","learn":"Mensen maken keuzes over ruimte. Landschap en verbindingen spelen daarbij een rol.","kind":"choice"}],"sources":[{"title":"Japan National Tourism Organization · Kanagawa","url":"https://www.japan.travel/en/destinations/kanto/kanagawa/"},{"title":"Japan National Tourism Organization · Fuji zien","url":"https://faq.japan-travel.jnto.go.jp/en/fuji-guide/views-of-fuji/"},{"title":"UNESCO · natuur en erfgoed bij dit verhaal","url":"https://whc.unesco.org/en/list/1418/"}],"version":"4c452f5557bc","memory_cue":"Fuji: Japanse berg, natuur én inspiratie voor kunst en geloof.","insight":{"version":1,"question":"Wat laat het voorbeeld van de Fuji zien?","options":["Een landschap kan voor verschillende mensen verschillende betekenissen hebben","Een berg is alleen een meetpunt zonder culturele betekenis","Iedere Japanner denkt precies hetzelfde over de berg"],"answer":0,"explanation":"Een berg is een natuurverschijnsel en kan tegelijk belangrijk zijn in kunst of religie. Betekenissen verschillen."}},{"id":"davi","lesson":"world-south","country":"br","child":"Davi","home":"Manaus","title":"Een stad bij twee kleuren water","bounds":[-75,-34,-34,7],"places":[{"id":"davi-manaus","name":"Manaus","lon":-60.02,"lat":-3.12,"kind":"city"},{"id":"br-cap","name":"Brasília","lon":-47.88,"lat":-15.79,"kind":"city"},{"id":"davi-meeting","name":"Samenkomst Rio Negro en Solimões","lon":-59.9,"lat":-3.14,"kind":"water"}],"scenes":[{"title":"Mijn straat bij de rivier","paragraphs":["Ik ben Davi en ik woon in Manaus. Na school spreek ik soms af met een vriend. We verzinnen een spel waarbij de bal tussen twee zelfgekozen doelpalen moet. Als mijn moeder me roept, wil ik altijd nog één keer proberen. In mijn straat zijn huizen en verkeer. Bij een uitstap naar het water kijk ik juist graag naar de boten. Manaus is een grote stad in het Amazonegebied.","Op de kaart van Brazilië zoek ik Manaus in het noorden van het land. Brasília, de hoofdstad, ligt verder naar het zuiden en oosten. Ik trek geen landsgrens tussen die twee stippen: ze liggen allebei in hetzelfde land. De grote afstand herinnert me eraan hoeveel verschillende plekken Brazilië heeft."],"points":["davi-manaus","br-cap"],"question":"In welke stad woont Davi?","options":["br-cap","davi-manaus"],"answer":"davi-manaus","explanation":"Davi woont in Manaus. Brasília is de hoofdstad van Brazilië.","learn":"Een stad in een regenwoudgebied is niet hetzelfde als een leeg stuk bos. Kijk naar mensen, gebouwen én landschap.","kind":"map"},{"title":"Het water ontmoet elkaar","paragraphs":["Bij Manaus komen de Rio Negro en de Solimões samen. Het donkere en lichtere water kan daar een tijd naast elkaar zichtbaar blijven. Op een foto lijkt het bijna alsof iemand een streep in de rivier heeft getrokken. Toch is het water niet voor altijd gescheiden: verder stroomafwaarts mengt het.","Ik wil weten waar die plek precies ligt. Een foto helpt me het kleurverschil te zien; de kaart helpt me de samenkomst bij Manaus te plaatsen. Ik schrijf de twee riviernamen erbij. Alleen “blauw water” op een kaart zou niet genoeg zijn om uit te leggen welke plek ik bedoel."],"points":["davi-manaus","davi-meeting"],"question":"Wat kun je van de foto en de kaart samen leren?","options":["Hoe het water eruitziet én waar de samenkomst ligt","Welke boot vandaag precies op tijd vertrekt","Dat de kleur van het water op iedere plek altijd hetzelfde blijft"],"answer":0,"explanation":"De bronnen vullen elkaar aan: uiterlijk en ligging. Het water mengt verder stroomafwaarts.","learn":"Water heeft eigenschappen en een loop. Kaarten en beelden helpen verschillende vragen beantwoorden.","kind":"choice"},{"title":"Een weg van water","paragraphs":["Op een kaart volg ik hoe rivieren plaatsen verbinden. Een boot kan voor sommige reizen of goederen belangrijk zijn. Dat betekent niet dat iedereen hier altijd per boot gaat. Mijn gewone dag ziet er anders uit dan een lange reis over de rivier. Voor een echte route moet je bovendien meer weten dan alleen waar de blauwe lijn ligt.","In de klas bedenken we wat er verandert als water hoger of lager staat. We vragen ons af wat dat kan betekenen voor een aanlegplaats of voor mensen die dicht bij water wonen. Ik zet een vraagteken in mijn schrift. De kaart helpt om de plek te begrijpen, maar om het antwoord te vinden moeten we verder onderzoeken.","Bij een natuurles hoor ik over bossen die een deel van het jaar onder water staan. In het Amazonegebied leven zelfs rivierdolfijnen! Ik had een dolfijn eerst alleen met zee verbonden. De rivier is hier dus een leefgebied én een verbinding voor mensen. Als bos verdwijnt of water vervuild raakt, verandert er meer dan één groen vlak op de kaart. Ik onthoud Manaus met een stad, een brede rivier en het bos eromheen. Het zijn buren in één landschap."],"points":["davi-manaus","br-cap"],"question":"Welke vraag gaat over een verband tussen water en het leven van mensen?","options":["Wat kan een veranderende waterstand betekenen voor een aanlegplaats?","Hoe spel je de naam van deze rivier?","Welke hoofdstad hoort bij dit land?"],"answer":0,"explanation":"De vraag verbindt een natuurverschijnsel aan wonen en vervoer.","learn":"Waterstand kan invloed hebben op gebruik van ruimte en verbindingen. Niet elke bewoner leeft op dezelfde manier.","kind":"choice"}],"sources":[{"title":"NASA Earth Observatory · samenkomst bij Manaus","url":"https://science.nasa.gov/earth/earth-observatory/solimaes-negro-river-confluence-at-manaus-amazonia-5254/"},{"title":"UNESCO · natuur en erfgoed bij dit verhaal","url":"https://whc.unesco.org/en/list/998/"}],"version":"e31047282eee","memory_cue":"Manaus: stad in het Amazonegebied; rivier, bos en leven hangen samen.","insight":{"version":1,"question":"Waarom is een rivier in het Amazonegebied meer dan een vaarroute?","options":["Het water is ook leefgebied voor dieren en hangt samen met het bos","Alle rivierdolfijnen leven uitsluitend in de oceaan","Veranderingen in het bos hebben nooit invloed op water"],"answer":0,"explanation":"Water, bos, dieren en mensen zijn met elkaar verbonden. Een kaartlijn vertelt maar een deel van dat verhaal."}},{"id":"maya","lesson":"world-north","country":"us","child":"Maya","home":"New York","title":"Mijn eiland tussen de bruggen","bounds":[-81,37,-70,46],"places":[{"id":"maya-newyork","name":"New York","lon":-74.01,"lat":40.71,"kind":"city"},{"id":"us-cap","name":"Washington D.C.","lon":-77.04,"lat":38.91,"kind":"city"},{"id":"maya-hudson","name":"Hudson bij New York","lon":-74.03,"lat":40.76,"kind":"river"}],"scenes":[{"title":"Een stad met water ertussen","paragraphs":["Ik ben Maya en ik woon in New York. Voor een bezoek aan mijn tante kijken we eerst welke trein we nemen. Mijn broertje wil gewoon een rechte lijn op de kaart volgen. Maar tussen sommige delen van de stad ligt water. Bruggen, tunnels en veerboten verbinden plekken die anders lastig bereikbaar zijn. Vanuit een trein zie ik veel minder dan op de kaart: soms rijden we onder de grond. Thuis teken ik onze reis na, met een ster bij het station waar ik bijna mijn muts vergat. Dat is mijn eigen herkenningspunt, ook al staat het niet in een atlas.","Bij de haven zie ik op een afbeelding het Vrijheidsbeeld. Frankrijk gaf het beeld aan de Verenigde Staten; het werd in 1886 geopend. Voor veel mensen die over zee aankwamen, werd het een herkenbaar teken van een nieuw begin. Ik vraag me af hoe spannend zo’n reis moest zijn. Migratie betekent dat mensen naar een andere plek verhuizen om daar te wonen. Ik onthoud New York met een haven en aankomende schepen, zonder te denken dat ieder gezin dezelfde reis heeft gemaakt."],"points":["maya-newyork","maya-hudson"],"question":"Wat helpt om tussen stadsdelen met water ertussen te reizen?","options":["Bruggen, tunnels en veerverbindingen","Alleen de rechte lijn tussen twee huizen","Alleen weten hoe groot de stad is"],"answer":0,"explanation":"Verbindingen maken reizen over of onder water mogelijk. Een rechte lijn is niet vanzelf een bruikbare route.","learn":"Water kan een stad verdelen; mensen leggen verbindingen aan.","kind":"choice"},{"title":"De hoofdstad is een andere stip","paragraphs":["Op school spreken we over de Verenigde Staten. Iemand wijst meteen naar New York als we de hoofdstad zoeken. Ik snap dat wel: mijn stad is groot en bekend. Toch moeten we Washington D.C. aanwijzen. Die stad ligt zuidelijker. Ik schrijf beide namen op mijn kaart. Daarna trek ik een kring om het hele land. New York is één stad in dat grote gebied. Wie alleen onze hoge gebouwen kent, heeft nog geen beeld van alle andere plekken waar Amerikaanse kinderen wonen. Ik zou graag eens weten hoe een schooldag eruitziet in een veel kleinere plaats."],"points":["maya-newyork","us-cap"],"question":"Welke stad is de hoofdstad van de Verenigde Staten?","options":["maya-newyork","us-cap"],"answer":"us-cap","explanation":"Washington D.C. is de hoofdstad. New York is een andere, grote stad.","learn":"Een grote of bekende stad hoeft niet de hoofdstad te zijn. Met Amerika bedoelen we hier het land Verenigde Staten.","kind":"map"},{"title":"Mijn ideale buurt","paragraphs":["Mijn vriendin wil een groter speelveld. Ik wil meer bomen langs onze looproute. We tekenen allebei een ontwerp voor hetzelfde stukje buurt. Alleen passen een extra weg, een park én een groot speelveld niet zomaar op dezelfde plek. We moeten kiezen. Op onze plattegrond tekenen we ook waar mensen wonen en waar het station is. Het wordt een echt gesprek: wie gebruikt deze ruimte en wat hebben die mensen nodig? Mijn broertje zet zijn favoriete winkel midden op het voetbalveld. Daar gaan de andere kinderen vast iets van vinden."],"points":["maya-newyork","maya-hudson"],"question":"Welke vraag helpt bij het ontwerpen van de buurt?","options":["Wie gebruikt de ruimte en wat hebben die mensen nodig?","Welke stad is het bekendst op televisie?","Hoeveel letters heeft de naam van de straat?"],"answer":0,"explanation":"Ruimte heeft meerdere gebruikers. Een ontwerp vraagt om afwegen van wensen en verbindingen.","learn":"Aardrijkskunde gaat ook over keuzes voor wonen, groen, spelen en vervoer.","kind":"choice"}],"sources":[{"title":"National Park Service · vervoer bij New York Harbor","url":"https://home.nps.gov/npnh/planyourvisit/directions.htm"},{"title":"UNESCO · natuur en erfgoed bij dit verhaal","url":"https://whc.unesco.org/en/list/307/"}],"version":"a88a062080a1","memory_cue":"New York: haven, Vrijheidsbeeld en verhalen over migratie.","insight":{"version":1,"question":"Welk verband hoort bij het Vrijheidsbeeld en New York?","options":["De havenligging en de geschiedenis van mensen die over zee aankwamen","New York is door het beeld de hoofdstad geworden","Iedere inwoner heeft dezelfde migratiegeschiedenis"],"answer":0,"explanation":"De plek bij de haven helpt om verhalen over aankomst en migratie te plaatsen. Washington D.C. is de hoofdstad."}},{"id":"sofia","lesson":"world-north","country":"mx","child":"Sofía","home":"Mexico-Stad","title":"Groen tussen de kanalen","bounds":[-103,18,-97,22],"places":[{"id":"mx-cap","name":"Mexico-Stad","lon":-99.13,"lat":19.43,"kind":"city"},{"id":"sofia-xochimilco","name":"Xochimilco","lon":-99.1,"lat":19.26,"kind":"city"},{"id":"sofia-puebla","name":"Puebla","lon":-98.21,"lat":19.04,"kind":"city"}],"scenes":[{"title":"Een hoofdstad met gewone ochtenden","paragraphs":["Ik ben Sofía en ik woon in Mexico-Stad. Op een schoolochtend zoek ik mijn schrift terwijl mijn broer zegt dat we moeten opschieten. Buiten is het druk. Op een kaart van Mexico zie ik onze stad als één stip, maar mijn eigen buurt voelt veel groter. Mexico-Stad is de hoofdstad van het land Mexico. Dat zijn twee namen voor twee verschillende ruimtelijke niveaus. Mijn vriendin woont aan de andere kant van de stad. “We wonen in dezelfde stip”, grap ik, “maar we kunnen niet zomaar even van het ene huis naar het andere springen.”"],"points":["mx-cap","sofia-puebla"],"question":"Waar woont Sofía?","options":["mx-cap","sofia-puebla"],"answer":"mx-cap","explanation":"Sofía woont in Mexico-Stad, de hoofdstad van Mexico. Eén kaartstip kan een heel groot stedelijk gebied voorstellen.","learn":"Maak onderscheid tussen het land Mexico en de stad Mexico-Stad.","kind":"map"},{"title":"Een tuin met water erlangs","paragraphs":["Bij een bezoek aan Xochimilco kijken we naar kanalen en stukken grond waar gewassen groeien. Die aangelegde landbouwpercelen heten chinampas. Ze zijn niet zomaar los ronddrijvende tuinen. Ik teken een smalle strook land met water ernaast. Mijn neef tekent alleen het water en vergeet waar de planten staan. We moeten lachen, maar verbeteren de tekening wel. Mensen hebben dit landschap mee gevormd. Als je alleen een moderne straat in het centrum ziet, vermoed je misschien niet dat dit ook bij de omgeving van Mexico-Stad hoort.","Bij Xochimilco zie ik dat voedsel verbouwen en water bij elkaar horen. De chinampas zijn stukken landbouwgrond tussen kanalen. Deze manier van boeren heeft wortels in de tijd vóór de Spaanse verovering. Het zijn geen losse vlotten die overal heen drijven. Ik teken een groen vak met blauw erlangs. Zo onthoud ik dat een grote stad ook een landschap met oude landbouwkennis kan bevatten. Bewaren betekent hier niet alleen naar vroeger kijken: mensen gebruiken en verzorgen het gebied nog steeds."],"points":["mx-cap","sofia-xochimilco"],"question":"Wat laat het voorbeeld van de chinampas zien?","options":["Dat mensen land en water gebruiken en het landschap vormgeven","Dat alle landbouwgrond los op het water drijft","Dat er rond een grote stad nooit landbouw is"],"answer":0,"explanation":"Chinampas zijn aangelegde landbouwpercelen tussen waterverbindingen.","learn":"Mens en landschap beïnvloeden elkaar. Een stad kan heel verschillende soorten ruimte bevatten.","kind":"choice"},{"title":"Een plek heeft meer dan één functie","paragraphs":["We bespreken waarom mensen het gebied willen bewaren. Er groeit voedsel, er komen bezoekers en er leven planten en dieren. Dat zijn verschillende functies van dezelfde omgeving. Mijn vriendin vraagt of meer bezoekers altijd beter is. Ik weet het niet meteen. We zouden ook moeten kijken naar wat bewoners en landbouwers nodig hebben. Voor ons verslag kiezen we een kaart, een foto en informatie over het gebied. Ik voeg mijn eigen tekening toe. Die laat zien wat mij opviel, maar is geen bewijs dat iedere plek er precies zo uitziet."],"points":["mx-cap","sofia-xochimilco"],"question":"Waarom onderzoek je meer dan alleen het aantal bezoekers?","options":["Ook bewoners, landbouw en natuur hebben belangen","Bezoekers bepalen altijd als enigen wat er gebeurt","Een gebied kan maar één functie hebben"],"answer":0,"explanation":"Dezelfde ruimte kan meerdere functies en gebruikers hebben.","learn":"Onderzoek verschillende belangen bij het gebruik en behoud van een landschap.","kind":"choice"}],"sources":[{"title":"UNESCO · Mexico-Stad en Xochimilco","url":"https://whc.unesco.org/en/list/412/"},{"title":"Mexicaans ministerie van Landbouw · chinampas","url":"https://www.gob.mx/agricultura/es/articulos/chinampas-una-herencia-prehispanica-de-cultivo"},{"title":"FAO · chinampas","url":"https://www.fao.org/giahs/around-the-world/detail/mexico-chinampas/en"}],"version":"0d085fe4f77a","memory_cue":"Mexico-Stad: bij Xochimilco landbouwgrond tussen kanalen, met een lange geschiedenis.","insight":{"version":1,"question":"Wat maakt de chinampas een voorbeeld van mens en landschap?","options":["Mensen gebruiken grond en kanalen om voedsel te verbouwen","Het zijn flatgebouwen zonder verbinding met water","Het water maakt landbouw per definitie onmogelijk"],"answer":0,"explanation":"De chinampas verbinden waterbeheer, voedselproductie en historische kennis."}},{"id":"noa","lesson":"world-kingdom","country":"curacao","child":"Noa","home":"Willemstad","title":"Een brug die ruimte maakt voor schepen","bounds":[-69.2,11.95,-68.7,12.4],"places":[{"id":"noa-willemstad","name":"Willemstad","lon":-68.93,"lat":12.11,"kind":"city"},{"id":"noa-christoffel","name":"Christoffelberg","lon":-69.12,"lat":12.34,"kind":"area"},{"id":"noa-bay","name":"Sint Annabaai","lon":-68.935,"lat":12.11,"kind":"water"}],"scenes":[{"title":"Aan de andere kant van het water","paragraphs":["Ik ben Noa en ik woon in Willemstad op Curaçao. Bij het water blijf ik graag even kijken naar wat er gebeurt. De Koningin Emmabrug verbindt delen van de stad en kan opzij draaien om schepen door te laten. Dan kun je niet gewoon blijven doorlopen alsof er niets verandert. Mijn broertje vindt het wachten vooral lang duren; ik vind het juist bijzonder dat een brug voor voetgangers én een doorgang voor schepen moet werken. Op mijn buurtkaart krijgt de brug een eigen teken. In de legenda leg ik uit wat dat betekent.","Als ik de oude gebouwen bij de haven bekijk, zie ik sporen van contacten met Europa en het Caribisch gebied. Het verleden van Willemstad hoort ook bij koloniale handel en slavernij: mensen werden tot slaaf gemaakt en gedwongen te werken. Dat onrecht mag niet verdwijnen achter alleen een vrolijke foto van gekleurde huizen. Een stad bewaren gaat ook om de verhalen van mensen. Ik onthoud Willemstad als een havenstad op Curaçao, met mooie gebouwen én een geschiedenis waarover je vragen moet blijven stellen."],"points":["noa-willemstad","noa-bay"],"question":"Waarom kan een beweegbare brug hier handig zijn?","options":["Voetgangers kunnen oversteken en schepen kunnen bij opening passeren","Dan zijn de twee oevers altijd afgesloten","Een brug maakt de hele baai ondiep"],"answer":0,"explanation":"De brug moet ruimte bieden aan verschillende vormen van vervoer.","learn":"Water is een verbinding voor schepen en kan tegelijk een oversteek voor voetgangers vragen.","kind":"choice"},{"title":"Een eiland en een land","paragraphs":["Een kind uit Europees Nederland vraagt of ik in Nederland woon. Ik moet even precies zijn. Ik woon in het land Curaçao. Dat is samen met Nederland, Aruba en Sint Maarten onderdeel van het Koninkrijk der Nederlanden. Bonaire hoort juist wel bij het land Nederland. De namen zijn best verwarrend als je ze voor het eerst hoort. Ik zet Willemstad op mijn eilandkaart en schrijf de hoofdstad erbij. Daarna bekijk ik een grotere kaart. Daarop zie ik dat Curaçao dicht bij de kust van Venezuela ligt, ver van Europees Nederland."],"points":["noa-willemstad","noa-christoffel"],"question":"Welke uitspraak klopt?","options":["Curaçao is een land binnen het Koninkrijk der Nederlanden","Curaçao is hetzelfde als het land Nederland","Alle Caribische eilanden vormen samen één provincie"],"answer":0,"explanation":"Curaçao is één van de vier landen van het Koninkrijk. Willemstad is de hoofdstad.","learn":"Een eiland, een land en een koninkrijk zijn verschillende begrippen.","kind":"choice"},{"title":"Niet overal dezelfde straat","paragraphs":["Bij een uitstap naar het noordwesten ziet mijn omgeving er anders uit dan in de stad. Bij het Christoffelpark ligt de Christoffelberg. Op mijn tekening staan opeens meer natuur en minder huizen. Toch horen beide tekeningen bij Curaçao. Ik wil de berg niet als een tweede stad op mijn kaart zetten. We gebruiken een ander symbool en kijken in de legenda. Voor mijn werkstuk kies ik een vraag: hoe verandert het gebruik van ruimte tussen de stad en een natuurgebied? Mijn broertje wil liever tekenen waar we ons broodje opaten. Dat mag als zijn eigen herinneringsplek."],"points":["noa-willemstad","noa-christoffel"],"question":"Welk kaartanker hoort bij het natuurgebied uit het verhaal?","options":["noa-willemstad","noa-christoffel"],"answer":"noa-christoffel","explanation":"De Christoffelberg ligt in het noordwestelijke deel van Curaçao. Willemstad is de stad uit het verhaal.","learn":"Vergelijk stedelijke ruimte en natuurgebied. Gebruik verschillende tekens voor verschillende objecten.","kind":"map"}],"sources":[{"title":"Curaçao Tourist Board · bruggen","url":"https://www.curacao.com/pt/article/bridges"},{"title":"Christoffelpark · natuurgebied","url":"https://www.christoffelpark.org/"},{"title":"Rijksoverheid · Koninkrijk","url":"https://www.rijksoverheid.nl/documenten/vraag-en-antwoord/caribische-deel-van-het-koninkrijk/waaruit-bestaat-het-koninkrijk-der-nederlanden"},{"title":"UNESCO · natuur en erfgoed bij dit verhaal","url":"https://whc.unesco.org/en/list/819/"},{"title":"Kurá Hulanda Museum · slavernij en koloniale geschiedenis","url":"https://kurahulandamuseum.com/the-museum/"}],"version":"1303eaffde98","memory_cue":"Willemstad: Caribische havenstad; gebouwen bewaren ook een moeilijke geschiedenis.","insight":{"version":1,"question":"Waarom vertelt alleen een foto van gekleurde huizen niet het hele verhaal?","options":["Bij de stad horen ook verhalen over koloniale handel en slavernij","Gebouwen kunnen nooit iets met geschiedenis te maken hebben","Een mooie foto bewijst dat er nooit onrecht was"],"answer":0,"explanation":"Erfgoed vraagt om meer dan uiterlijk: je onderzoekt ook wiens verhalen en ervaringen erbij horen."}},{"id":"bela","lesson":"world-south","country":"br","child":"Bela","home":"Rio de Janeiro","title":"Mijn stad tussen zee en bergen","bounds":[-66,-25,-42,1],"places":[{"id":"bela-rio","name":"Rio de Janeiro","lon":-43.17,"lat":-22.91,"kind":"city"},{"id":"br-cap","name":"Brasília","lon":-47.88,"lat":-15.79,"kind":"city"},{"id":"davi-manaus","name":"Manaus","lon":-60.02,"lat":-3.12,"kind":"city"}],"scenes":[{"title":"Een bal die niet de straat op mag","paragraphs":["Ik ben Bela en ik woon in Rio de Janeiro. Met mijn vriendin spreek ik af waar we zullen spelen. Zij kiest een plekje met schaduw. Ik wil vooral dat de bal niet steeds wegrolt. Op een foto van onze stad zie je zee, gebouwen en bergen dicht bij elkaar. In mijn gewone middag gaat het ook gewoon over vrienden, huiswerk en waar mijn schoenen liggen. Als ik Rio op de kaart zoek, zie ik dat het aan de Atlantische kust ligt. Vergeleken met een foto zie je op de kaart weer andere dingen."],"points":["bela-rio","br-cap"],"question":"In welke stad woont Bela?","options":["bela-rio","br-cap"],"answer":"bela-rio","explanation":"Bela woont in Rio de Janeiro, aan de Atlantische kust. Brasília ligt in het binnenland.","learn":"Een kaart laat ligging zien; een foto kan landschap en bebouwing tonen.","kind":"map"},{"title":"Een bericht van Davi","paragraphs":["Voor een schoolproject lees ik een verhaal van Davi uit Manaus. Hij woont ook in Brazilië, maar zijn omgeving is niet hetzelfde als de mijne. Bij hem spelen grote rivieren een belangrijke rol; ik vertel over de kust en de bergen bij mijn stad. We zoeken onze twee stippen op. Ze liggen een enorme afstand uit elkaar. Daarna zetten we Brasília erbij, de hoofdstad. We besluiten niet te schrijven dat één van onze buurten het echte Brazilië is. Onze verhalen zijn twee verschillende vensters op hetzelfde grote land."],"points":["bela-rio","davi-manaus","br-cap"],"question":"Waarom vullen Bela’s en Davi’s verhalen elkaar aan?","options":["Ze laten verschillende omgevingen binnen hetzelfde land zien","Ze wonen in twee landen met toevallig dezelfde naam","Eén van beide omgevingen kan niet in Brazilië liggen"],"answer":0,"explanation":"Rio de Janeiro en Manaus liggen allebei in Brazilië, maar in heel verschillende omgevingen.","learn":"Vergelijk perspectieven en verschillen binnen een land.","kind":"choice"},{"title":"Wie gebruikt het groen?","paragraphs":["Bij een gesprek over onze buurt wil ik meer plek om te spelen. Iemand anders denkt aan woningen en weer iemand aan ruimte voor verkeer. Op een kaart tekenen we het groen dat er al is. Op een foto zien we beter hoe die plek eruitziet. De bergen en de zee betekenen dat je niet overal zomaar kunt bouwen of een weg kunt aanleggen. We moeten dus nadenken over hoe mensen en landschap samen de stad vormen. Mijn eerste plan past niet helemaal. Ik schuif het speelveld een stukje op en leg uit waarom.","Op een kaart van Rio zie ik dat hoge vormen en zee dicht bij de stad liggen. De bergen van het Tijucagebied, de baai en de ingerichte kust hebben de stad mee gevormd. Een strand om te spelen vraagt andere ruimte dan een steile helling. Mensen hebben tuinen en wandelplekken aangelegd, maar konden de bergen niet zomaar wegdenken. Ik maak een geheugenplaatje met drie lagen: berg, stad, zee. Davi zou voor zijn omgeving bij Manaus een ander plaatje maken, hoewel we allebei in Brazilië wonen."],"points":["bela-rio","br-cap"],"question":"Welke informatie helpt bij het kiezen van een plek voor een speelveld?","options":["Bestaande bebouwing, landschap en de wensen van gebruikers","Alleen welke stad de hoofdstad is","Alleen de kleur van het stadssymbool"],"answer":0,"explanation":"Je combineert informatie over de plek met wensen van mensen.","learn":"Ruimtegebruik vraagt om keuzes. Landschap en bestaande bebouwing spelen mee.","kind":"choice"}],"sources":[{"title":"Visit Brasil · Rio de Janeiro","url":"https://www.visitbrasil.com/en/location/rio-de-janeiro-en"},{"title":"Visit Brasil · Brasília","url":"https://www.visitbrasil.com/en/location/brasilia/"},{"title":"UNESCO · natuur en erfgoed bij dit verhaal","url":"https://whc.unesco.org/en/list/1100/"}],"version":"0f38dfb98f7b","memory_cue":"Rio: berg, stad en zee; Manaus: stad, rivier en Amazonebos.","insight":{"version":1,"question":"Waarom moet je in Rio bij een nieuw speelveld ook naar het reliëf kijken?","options":["Steile hellingen en bestaande bebouwing beperken geschikte plekken","Iedere plek in Rio is vlak en onbebouwd","Een landkaart garandeert dat overal ruimte vrij is"],"answer":0,"explanation":"De vorm van het landschap en het bestaande ruimtegebruik beïnvloeden keuzes voor recreatie."}},{"id":"lani","lesson":"world-oceania","country":"fj","child":"Lani","home":"Suva","title":"Ons eiland heeft meer dan één kant","bounds":[176.8,-18.8,179,-16.9],"places":[{"id":"fj-cap","name":"Suva","lon":178.45,"lat":-18.14,"kind":"city"},{"id":"lani-nadi","name":"Nadi","lon":177.44,"lat":-17.8,"kind":"city"},{"id":"lani-lautoka","name":"Lautoka","lon":177.45,"lat":-17.61,"kind":"city"}],"scenes":[{"title":"Mijn schooltas gaat ook mee","paragraphs":["Ik ben Lani en ik woon in Suva op het eiland Viti Levu in Fiji. Voor school controleer ik of mijn schrift in mijn tas zit. Daarna vraag ik mijn vriendin of ze na school tijd heeft. Mensen die Fiji alleen van vakantiefoto’s kennen, denken misschien eerst aan een strand. Mijn dagen hebben ook schoolwerk, straten en afspraken. Suva is bovendien de hoofdstad van Fiji. Op de kaart van ons eiland zie ik de stad aan de zuidoostkant. Ik zet er een stip bij en schrijf niet alleen eiland, maar ook de naam van de stad."],"points":["fj-cap","lani-nadi"],"question":"Waar woont Lani?","options":["lani-nadi","fj-cap"],"answer":"fj-cap","explanation":"Lani woont in Suva, de hoofdstad van Fiji, op Viti Levu.","learn":"Fiji is een land met meerdere eilanden. Viti Levu is een eiland; Suva is een stad.","kind":"map"},{"title":"De rit naar mijn neef","paragraphs":["Mijn neef woont bij Nadi, aan de andere kant van Viti Levu. We bekijken hoe we hem kunnen bezoeken. Op de kaart loopt mijn vinger dwars door het eiland. De echte bus volgt natuurlijk de weg. Die kan langs de kust lopen en bochten maken. Nadi heeft ook een belangrijke luchthaven. Niet iedereen die daar aankomt, blijft in dezelfde plaats. Ik teken een koffertje bij de luchthaven en een bus bij de weg. Met die twee tekens kan ik uitleggen hoe verschillende verbindingen op elkaar aansluiten."],"points":["fj-cap","lani-nadi","lani-lautoka"],"question":"Waarom is de lijn dwars over het eiland niet genoeg om een busreis te plannen?","options":["De bus moet bestaande wegen volgen","Op een eiland rijden nooit bussen","De luchthaven bepaalt iedere bushalte"],"answer":0,"explanation":"Voor de echte route heb je een wegen- of vervoerskaart nodig.","learn":"Een eiland heeft ook landverbindingen. Hemelsbreed is niet hetzelfde als de route.","kind":"choice"},{"title":"Van mijn eiland naar een ander","paragraphs":["We maken een kaartspel met de eilanden van Fiji. Ik mag Viti Levu niet per ongeluk als het hele land behandelen. Voor een bezoek aan een ander eiland kan een boot of vliegtuig nodig zijn. Voor een bezoek op hetzelfde eiland kan de weg juist handig zijn. Mijn vriendin vraagt welke verbinding het beste is. Dat hangt af van waar je begint, waar je heen wilt en wat er beschikbaar is. Eén tekening van een boot vertelt dus nog niet hoe iedereen zich verplaatst. Ik wil onze kaart ook de stad en de wegen laten zien.","In een boek vinden we Levuka op het eiland Ovalau. Het was vroeger de hoofdstad van Fiji; nu is dat Suva op Viti Levu. Bij Levuka vertellen oude havengebouwen over handel en over contacten tussen eilandbewoners en mensen van buiten. Ik teken twee eilandjes met elk een stip. Die stippen zijn geen buren in dezelfde straat: er ligt zee tussen. Geschiedenis helpt me zo om twee plaatsen te onderscheiden, en de kaart helpt me begrijpen waarom een bezoek meer vraagt dan de busrit op ons eigen eiland."],"points":["fj-cap","lani-nadi"],"question":"Wat moet je eerst weten bij het kiezen van vervoer?","options":["Beginpunt, bestemming en beschikbare verbindingen","Alleen dat Fiji eilanden heeft","Alleen welke stad de hoofdstad is"],"answer":0,"explanation":"Ligging en echte verbindingen bepalen samen de mogelijkheden.","learn":"Een eilandland heeft verschillende soorten verbindingen en dagelijks leven.","kind":"choice"}],"sources":[{"title":"Tourism Fiji · Suva","url":"https://www.fiji.travel/places-to-go/suva/locations/suva-the-heartbeat-of-the-pacific"},{"title":"Tourism Fiji · landvervoer","url":"https://www.fiji.travel/things-to-know/getting-around/land-airport-transfers"},{"title":"UNESCO · natuur en erfgoed bij dit verhaal","url":"https://whc.unesco.org/en/list/1399/"}],"version":"27d626d974d0","memory_cue":"Fiji: Suva op Viti Levu; Levuka, de vroegere hoofdstad, op een ander eiland.","insight":{"version":1,"question":"Wat leer je door Suva en Levuka te vergelijken?","options":["Een hoofdstad kan veranderen en de plaatsen liggen op verschillende eilanden","Suva en Levuka zijn twee namen voor dezelfde straat","Elke reis binnen Fiji kan volledig per bus"],"answer":0,"explanation":"Historische verandering en ligging vullen elkaar aan. Zee tussen eilanden vraagt om een passende verbinding."}},{"id":"thandi","lesson":"world-africa","country":"za","child":"Thandi","home":"Kaapstad","title":"De berg achter mijn buurt","bounds":[17,-35,32,-22],"places":[{"id":"thandi-capetown","name":"Kaapstad","lon":18.42,"lat":-33.93,"kind":"city"},{"id":"za-cap","name":"Pretoria","lon":28.19,"lat":-25.75,"kind":"city"},{"id":"thandi-table","name":"Tafelberg","lon":18.41,"lat":-33.96,"kind":"area"}],"scenes":[{"title":"Een wolk op de berg","paragraphs":["Ik ben Thandi en ik woon in Kaapstad. Soms zit er een wolk over de Tafelberg en lijkt het alsof iemand er een kleed op heeft gelegd. Mijn broer zegt dat de berg verstoppertje speelt. Ik zie hem niet vanuit iedere straat, maar op een kaart kan ik zijn ligging terugvinden. De berg is geen stadsdeel en de stad is geen gebergte. Mijn eigen buurt heeft huizen, winkels en plekken waar ik mijn vrienden ontmoet. Het landschap vormt een mooie achtergrond, maar het kan ook invloed hebben op waar wegen en gebouwen passen.","Bij een wandeling horen we het woord fynbos. Het is begroeiing met veel soorten struiken en andere planten, kenmerkend voor het gebied rond de Kaap. Sommige soorten komen alleen in deze regio voor. Dat heet endemisch. Ik dacht bij bijzondere natuur eerst aan grote dieren, maar een klein plantje kan ook heel bijzonder zijn. Mijn plaatje bij Kaapstad krijgt een berg met planten ervoor. Zo onthoud ik de zuidwestelijke hoek van Zuid-Afrika en waarom mensen dit landschap willen beschermen."],"points":["thandi-capetown","thandi-table"],"question":"Welke combinatie helpt om de ligging en het uiterlijk van de berg te onderzoeken?","options":["Een kaart en een foto","Alleen een lijst met hoofdsteden","Alleen de naam van de wijk"],"answer":0,"explanation":"De kaart helpt bij ligging; een foto laat zien hoe de berg er op een moment uitziet.","learn":"Landschap en stad liggen hier dicht bij elkaar, maar blijven verschillende geografische objecten.","kind":"choice"},{"title":"Een lastige hoofdstadvraag","paragraphs":["Op school krijg ik de vraag wat de hoofdstad van Zuid-Afrika is. Ik wil niet zomaar één naam roepen. Ons land heeft verschillende hoofdsteden met verschillende functies. Pretoria is de bestuurlijke hoofdstad, Kaapstad de wetgevende hoofdstad en Bloemfontein de gerechtelijke hoofdstad. In Kaapstad zit het parlement. Ik schrijf de functies erbij, want anders wordt het een verwarrend rijtje. Mijn vriend stelt voor dat we de vraag preciezer maken: welke hoofdstad wordt bedoeld? Dat vind ik een beter plan dan één goed antwoord gokken op een onduidelijke vraag."],"points":["thandi-capetown","za-cap"],"question":"Welke stad is de bestuurlijke hoofdstad van Zuid-Afrika?","options":["thandi-capetown","za-cap"],"answer":"za-cap","explanation":"Pretoria is de bestuurlijke hoofdstad. Kaapstad en Bloemfontein hebben andere hoofdstedelijke functies.","learn":"Sommige landen hebben meer dan één hoofdstad of bestuurszetel. Lees de vraag precies.","kind":"map"},{"title":"Een park in ons plan","paragraphs":["Voor een buurtproject tekenen we een plek met groen. Ik wil ruimte om buiten te spelen. Een buurvrouw wil een rustige wandelplek. We bekijken ook waar verkeer rijdt en hoe je veilig bij het groen komt. De kaart helpt ons om die functies naast elkaar te zetten. Mijn broer tekent eerst een speelveld op een steile helling. Dat zou voor de bal nogal onhandig zijn. We verplaatsen het en leggen uit waarom. Zo merk ik dat aardrijkskunde ook gaat over gewone keuzes in de omgeving waar ik elke dag ben."],"points":["thandi-capetown","thandi-table"],"question":"Waarom bekijken de kinderen ook het reliëf bij hun ontwerp?","options":["Een steile helling kan invloed hebben op het gebruik van de plek","Iedere groene plek is vanzelf vlak","Een stadsnaam vertelt precies hoe steil een straat is"],"answer":0,"explanation":"Hoogteverschillen beïnvloeden mogelijkheden voor bouwen, spelen en vervoer.","learn":"Gebruik kaarten om keuzes voor de eigen leefomgeving te onderbouwen.","kind":"choice"}],"sources":[{"title":"Zuid-Afrikaanse overheid · hoofdsteden","url":"https://www.gov.za/about-sa/south-africa-glance"},{"title":"UNESCO · natuur en erfgoed bij dit verhaal","url":"https://whc.unesco.org/en/list/1007/"}],"version":"0aa9dbd761f6","memory_cue":"Kaapstad: zuidwesthoek van Zuid-Afrika, Tafelberg en bijzonder fynbos.","insight":{"version":1,"question":"Waarom kan een klein plantje in het Kaapgebied bescherming verdienen?","options":["Sommige soorten komen alleen in deze regio voor","Alleen grote dieren kunnen bijzonder zijn","Dezelfde soorten groeien noodzakelijk overal op aarde"],"answer":0,"explanation":"Soorten met een beperkt verspreidingsgebied kunnen niet zomaar ergens anders voortbestaan."}},{"id":"omar","lesson":"world-africa","country":"eg","child":"Omar","home":"Caïro","title":"Een groene strook langs de rivier","bounds":[25,23,35,32],"places":[{"id":"eg-cap","name":"Caïro","lon":31.24,"lat":30.04,"kind":"city"},{"id":"omar-alex","name":"Alexandrië","lon":29.92,"lat":31.2,"kind":"city"},{"id":"omar-nile","name":"Nijl bij Caïro","lon":31.23,"lat":30.05,"kind":"river"}],"scenes":[{"title":"De brug op onze route","paragraphs":["Ik ben Omar en ik woon in Caïro, de hoofdstad van Egypte. Als we een brug over de Nijl nemen, kijk ik graag even naar het water. Mijn zus wil vooral weten of we op tijd zijn. In mijn stad zijn drukke straten, scholen en huizen. Op een kaart wordt dat allemaal heel klein. De Nijl blijft als een lange lijn zichtbaar. Ik probeer te begrijpen waarom die rivier op zoveel kaarten belangrijk is. Mijn eerste vraag is eenvoudig: waar ligt mijn eigen stad ten opzichte van het water? Daarna wil ik verder stroomafwaarts kijken."],"points":["eg-cap","omar-alex"],"question":"Waar woont Omar?","options":["omar-alex","eg-cap"],"answer":"eg-cap","explanation":"Omar woont in Caïro, de hoofdstad van Egypte, bij de Nijl.","learn":"Een rivier kan een belangrijk herkenningspunt en een verbinding in een stad zijn.","kind":"map"},{"title":"Groen op het satellietbeeld","paragraphs":["Op een satellietbeeld zie ik een groene strook langs de Nijl en een bredere groene waaier in het noorden. Dat is anders dan de drogere omgeving ernaast. In de Nijldelta splitst de rivier zich voordat het water de Middellandse Zee bereikt. Water is belangrijk voor landbouw. Mijn tekening van een rivier met een paar streepjes blijkt dus maar een heel klein deel van het verhaal. De juf vraagt of groen op een beeld automatisch betekent dat er regenwoud ligt. Nee: we moeten ook naar het gebruik van de grond en aanvullende informatie kijken.","Bij Gizeh staan piramiden die horen bij de geschiedenis van het oude Egypte. Het zijn grafmonumenten; het waren geen gewone woonhuizen voor iedereen. Op school verbinden we het verhaal met de Nijl: langs water konden mensen voedsel verbouwen en nederzettingen laten groeien. Ik teken een blauwe rivier, een groene strook en een piramide. Dat helpt me het landschap te onthouden. Het Egypte van nu is natuurlijk meer dan de oudheid: mijn eigen school, verkeer en nieuwe gebouwen horen er net zo goed bij."],"points":["eg-cap","omar-alex"],"question":"Wat helpt verklaren waarom er landbouw langs de Nijl mogelijk is?","options":["De beschikbaarheid van water","Alleen dat het land een hoofdstad heeft","Dat ieder groen vlak een regenwoud is"],"answer":0,"explanation":"Water uit de rivier is belangrijk voor landbouw. Een satellietkleur moet je met andere informatie interpreteren.","learn":"Water, bodemgebruik en bewoning hangen samen. Een delta is een vertakkend riviermondingsgebied.","kind":"choice"},{"title":"Een kaartje van de kust","paragraphs":["Mijn tante stuurt een foto uit Alexandrië. Achter haar zie ik zee. Ik zoek haar stad op en ontdek dat die noordwestelijker ligt dan Caïro. We wonen in hetzelfde land, maar haar foto laat een andere omgeving zien. Voor mijn verslag zet ik mijn stadsfoto, het satellietbeeld en haar kustfoto naast elkaar. Ik schrijf bij ieder beeld wat het laat zien. Eén foto van zand of een oud bouwwerk zou mijn gewone leven niet volledig uitleggen. Ik wil juist laten zien hoe een rivier, een grote stad en de kust met elkaar verbonden kunnen zijn."],"points":["eg-cap","omar-alex"],"question":"Welke stad uit het verhaal ligt aan de Middellandse Zee?","options":["eg-cap","omar-alex"],"answer":"omar-alex","explanation":"Alexandrië ligt aan de Middellandse Zee. Caïro ligt verder landinwaarts bij de Nijl.","learn":"Vergelijk verschillende plekken binnen een land met passende kaarten en beelden.","kind":"map"}],"sources":[{"title":"ESA · rand van de Nijldelta","url":"https://www.esa.int/Applications/Observing_the_Earth/Earth_from_Space_Delta_s_edge"},{"title":"NASA · landbouw in de Nijldelta","url":"https://science.nasa.gov/earth/earth-observatory/the-nile-deltas-disappearing-farmland-149183/"},{"title":"UNESCO · natuur en erfgoed bij dit verhaal","url":"https://whc.unesco.org/en/list/86/"}],"version":"c8d3c23e7c9b","memory_cue":"Egypte: Nijl, landbouw langs water en piramiden uit het verleden.","insight":{"version":1,"question":"Waarom is de Nijl belangrijk in een verhaal over bewoning in Egypte?","options":["Water helpt landbouw en bewoning mogelijk te maken in een droge omgeving","Alle Egyptenaren wonen nu in piramiden","Een rivier verhindert overal dat mensen voedsel verbouwen"],"answer":0,"explanation":"Water, voedselvoorziening en bewoning hangen samen. Piramiden zijn historische grafmonumenten, geen beeld van alle huidige woningen."}},{"id":"sasha","lesson":"eu-oost","country":"ru","child":"Sasha","home":"Moskou","title":"Een neef aan de andere kant van de kaart","bounds":[25,45,115,68],"places":[{"id":"ru-cap","name":"Moskou","lon":37.62,"lat":55.75,"kind":"city"},{"id":"sasha-irkutsk","name":"Irkoetsk","lon":104.29,"lat":52.29,"kind":"city"},{"id":"sasha-baikal","name":"Baikalmeer","lon":108,"lat":53.5,"kind":"water"}],"scenes":[{"title":"Mijn gewone begin van de dag","paragraphs":["Ik ben Sasha en ik woon in Moskou, de hoofdstad van Rusland. Voor school kijk ik of ik mijn boek en handschoenen nodig heb. Dat laatste hangt af van het weer en het seizoen. Mijn vriend woont niet ver van mij, maar op een kaart van het hele land passen onze huizen in hetzelfde piepkleine gebied. Rusland is enorm uitgestrekt. Een deel ligt in Europa en een groot deel in Azië. Om mijn eigen buurt uit te leggen heb ik dus een veel gedetailleerdere kaart nodig. Anders verdwijnen de straten waar ik iedere dag loop."],"points":["ru-cap","sasha-irkutsk"],"question":"Waar woont Sasha?","options":["ru-cap","sasha-irkutsk"],"answer":"ru-cap","explanation":"Sasha woont in Moskou. Irkoetsk ligt veel verder naar het oosten.","learn":"Een landkaart en een buurtkaart laten verschillende ruimtelijke niveaus zien.","kind":"map"},{"title":"Een bericht uit Irkoetsk","paragraphs":["Mijn neef bij Irkoetsk stuurt een foto van het Baikalmeer. Ik wil meteen weten of het vlak bij ons is. Op de kaart zie ik hoeveel ruimte er tussen onze steden ligt. We spreken af wanneer we zullen bellen; het is niet overal in het grote land op hetzelfde moment dezelfde kloktijd. Voor de precieze afspraak controleren we dat even. Ik wil zijn foto niet verwarren met een zee: het Baikalmeer is een groot zoetwatermeer in Siberië. Mijn neef heeft zijn eigen schooldag en zijn eigen plekken die voor hem belangrijk zijn.","Bij het Baikalmeer zet mijn neef een klein dier op zijn tekening. In dit oude, diepe zoetwatermeer leven bijzondere soorten die je niet overal vindt. Dat het zo lang bestaat en betrekkelijk geïsoleerd ligt, helpt die eigen natuur te begrijpen. Mijn kaartje van Rusland krijgt dus niet alleen Moskou in het westen, maar ook een groot meer ver naar het oosten. Een land kan heel verschillende leefgebieden bevatten. Daarom wil ik bij een foto weten waar die precies is gemaakt."],"points":["sasha-irkutsk","sasha-baikal"],"question":"Wat is het Baikalmeer?","options":["Een zoetwatermeer in Siberië","Een zee tussen Moskou en Europa","Een andere naam voor de hoofdstad"],"answer":0,"explanation":"Het Baikalmeer is een groot en diep zoetwatermeer in Siberië.","learn":"Grote afstanden gaan samen met verschillende regio’s en tijdzones. Een meer is niet hetzelfde als een zee.","kind":"choice"},{"title":"Een foto is niet het hele jaar","paragraphs":["Een klasgenoot ziet een winterfoto van mijn neef en denkt dat het daar altijd zo uitziet. Ik stuur er een foto uit een ander seizoen bij. Voor het klimaat hebben we meer nodig dan die twee momenten: gegevens over langere tijd. We schrijven bij elke foto waar en wanneer die is gemaakt. Dat helpt ons ook nieuwsbeelden beter te plaatsen. Mijn eigen verhaal gaat over mijn buurt en familie. Om grote gebeurtenissen of actuele grenzen te begrijpen, gebruiken we andere betrouwbare bronnen. Een persoonlijk verhaal kan niet al die informatie vervangen."],"points":["ru-cap","sasha-irkutsk","sasha-baikal"],"question":"Waarom schrijf je plaats en seizoen bij een landschapsfoto?","options":["Om het beeld in de juiste geografische en tijdscontext te plaatsen","Omdat één winterfoto het hele klimaat bewijst","Omdat de hoofdstad bepaalt welk seizoen het overal is"],"answer":0,"explanation":"Een foto laat een plek op een bepaald moment zien. Voor klimaat en actualiteit zijn aanvullende bronnen nodig.","learn":"Vergelijk bronnen en vermijd conclusies over een heel land op basis van één beeld.","kind":"choice"}],"sources":[{"title":"UNESCO · Baikalmeer","url":"https://whc.unesco.org/en/list/754/"}],"version":"0000c8e17739","memory_cue":"Rusland: Moskou in het westen; het Baikalmeer ver oostelijker in Siberië.","insight":{"version":1,"question":"Wat helpt de bijzondere natuur van het Baikalmeer te begrijpen?","options":["De hoge ouderdom en de geïsoleerde ligging van het meer","Dat het meer de Atlantische Oceaan is","Dat heel Rusland één en hetzelfde leefgebied is"],"answer":0,"explanation":"De geschiedenis en ligging van een leefgebied helpen verschillen in natuur te verklaren."}},{"id":"lin","lesson":"world-asia","country":"cn","child":"Lin","home":"Shanghai","title":"Schepen voorbij mijn stad","bounds":[103,27,123,42],"places":[{"id":"lin-shanghai","name":"Shanghai","lon":121.47,"lat":31.23,"kind":"city"},{"id":"cn-cap","name":"Beijing","lon":116.4,"lat":39.9,"kind":"city"},{"id":"lin-delta","name":"Delta van de Jangtsekiang","lon":121.3,"lat":31.5,"kind":"water"}],"scenes":[{"title":"Een stad vol verbindingen","paragraphs":["Ik ben Lin en ik woon in Shanghai. Als we op pad gaan, kiezen we soms de metro. Dan moet ik goed bijhouden bij welk station we eruit moeten. Mijn broer telt de haltes, ik zoek de lijn op het kaartje. Boven de grond ziet de stad er anders uit dan op dat gekleurde schema. Een metrokaart maakt verbindingen overzichtelijk; niet alle bochten en afstanden zijn er precies op getekend. Op de landenkaart zoek ik daarna Shanghai aan de oostkant van China. Dat is weer een ander soort kaart, voor een andere vraag."],"points":["lin-shanghai","cn-cap"],"question":"Waar woont Lin?","options":["lin-shanghai","cn-cap"],"answer":"lin-shanghai","explanation":"Lin woont in Shanghai. Beijing is de hoofdstad van China.","learn":"Een schematische vervoerskaart en een geografische kaart hebben verschillende functies.","kind":"map"},{"title":"Waar rivier en zee elkaar ontmoeten","paragraphs":["Op een satellietbeeld zoeken we de omgeving van Shanghai in de delta van de Jangtsekiang. Er liggen steden, landbouwgebieden en waterverbindingen. Ik zie waarom een haven op een plek met verbindingen belangrijk kan zijn. Maar om te weten waar een specifiek schip vandaan komt, is deze kaart niet genoeg. Daarvoor heb ik informatie over dat schip nodig. Mijn vriend tekent een denkbeeldige route voor een doos speelgoed. We moeten steeds uitleggen welk deel echt uit onze bronnen volgt en welk deel we zelf hebben bedacht."],"points":["lin-shanghai","lin-delta"],"question":"Welke informatie heb je extra nodig om de echte reis van één schip te kennen?","options":["Gegevens over het schip en zijn route","Alleen de kleur van het water op de kaart","Alleen weten waar Beijing ligt"],"answer":0,"explanation":"Een liggingkaart toont mogelijkheden en verbanden, niet automatisch de reis van een afzonderlijk schip.","learn":"Een delta kan verschillende soorten ruimte en verbindingen bevatten. Maak onderscheid tussen bewijs en een verzonnen voorbeeld.","kind":"choice"},{"title":"Een logeerplan naar het noorden","paragraphs":["Voor een bezoek aan familie in Beijing bekijken we de kaart. Die stad ligt noordelijker en is de hoofdstad. De afstand tussen de twee stippen is groot, ook al passen ze samen op mijn scherm. Ik schrijf geen reistijd op voordat we een echte verbinding hebben bekeken. Mijn oma vraagt wat ik wil zien. Ik wil vooral weten hoe haar buurt verschilt van de mijne. In hetzelfde land kunnen landschap, weer en dagelijkse routes heel anders zijn. Daarom neem ik een klein schrift mee waarin ik mijn eigen waarnemingen wil opschrijven.","Bij Beijing laat mijn tante een foto van de Chinese Muur zien. Het is geen stadsmuur om heel China: verschillende delen werden in verschillende tijden aangelegd voor verdediging. Zo’n bouwwerk vertelt iets over macht en grenzen in het verleden. Shanghai herken ik juist aan rivier en zee in het oosten. Mijn geheugenkaart heeft daardoor twee verschillende beelden. Ik mag de oude muur niet aanzien voor de huidige landsgrens; een historische kaart en een kaart van nu kunnen andere dingen laten zien."],"points":["lin-shanghai","cn-cap"],"question":"Welke stad ligt noordelijker?","options":["lin-shanghai","cn-cap"],"answer":"cn-cap","explanation":"Beijing ligt noordelijker dan Shanghai. Op deze kaart staat noord boven.","learn":"Vergelijk ligging en omgeving binnen een groot land. Een schermgrootte zegt niet hoe lang de echte reis duurt.","kind":"map"}],"sources":[{"title":"NASA · groei en ligging van Shanghai","url":"https://science.nasa.gov/earth/earth-observatory/sprawling-shanghai-89853/"},{"title":"UNESCO · natuur en erfgoed bij dit verhaal","url":"https://whc.unesco.org/en/list/438/"}],"version":"b0bbe5741c2b","memory_cue":"Shanghai: rivier en zee; bij Beijing: muurgeschiedenis in het noorden.","insight":{"version":1,"question":"Waarom is de Chinese Muur geen betrouwbare kaart van de huidige landsgrens?","options":["Het is een historisch verdedigingswerk, gebouwd in verschillende tijden","Elke oude muur is automatisch de huidige landsgrens","Shanghai en Beijing zijn dezelfde stad"],"answer":0,"explanation":"Historische verdedigingswerken en huidige bestuurlijke grenzen zijn verschillende soorten informatie."}},{"id":"arjun","lesson":"world-asia","country":"in","child":"Arjun","home":"Mumbai","title":"De bal en de regenbui","bounds":[68,7,90,31],"places":[{"id":"arjun-mumbai","name":"Mumbai","lon":72.88,"lat":19.08,"kind":"city"},{"id":"in-cap","name":"New Delhi","lon":77.21,"lat":28.61,"kind":"city"},{"id":"arjun-chennai","name":"Chennai","lon":80.27,"lat":13.08,"kind":"city"}],"scenes":[{"title":"Nog één keer spelen","paragraphs":["Ik ben Arjun en ik woon in Mumbai, aan de westkust van India. Na school wil ik soms nog met mijn vrienden spelen. Dan let ik ook op de lucht. In de regentijd kan een bui onze plannen veranderen. Mijn vriend wil de bal nog één keer gooien; ik wil eerst weten waar mijn tas droog kan staan. Niet iedere dag is hetzelfde, en niet iedere plek in India heeft hetzelfde weer. Op de kaart zoek ik mijn kuststad. New Delhi, de hoofdstad, ligt een heel eind verder naar het noorden.","In Mumbai bekijken we een oud stationsgebouw met torens en bogen: Chhatrapati Shivaji Terminus. Het ontwerp verbindt Europese bouwvormen met Indiase tradities. Het gebouw ontstond in de tijd van Brits koloniaal bestuur. Een station is dus niet alleen handig voor treinen; het kan ook een bron over het verleden zijn. Ik teken een trein bij mijn kuststad. Daarna vraag ik wie hier bouwde en werkte, en wiens verhalen je in een beschrijving van zo’n gebouw terugvindt."],"points":["arjun-mumbai","in-cap"],"question":"Waar woont Arjun?","options":["arjun-mumbai","in-cap"],"answer":"arjun-mumbai","explanation":"Arjun woont in Mumbai, aan de westkust. New Delhi is de hoofdstad van India.","learn":"Kustligging en seizoen helpen bij het begrijpen van de omgeving.","kind":"map"},{"title":"Regen die belangrijk én lastig kan zijn","paragraphs":["Op school leren we over de moesson. Daarbij verandert de overheersende wind met het seizoen; de zomermoesson brengt in grote delen van India veel regen. Water is belangrijk voor gewassen en voor mensen. Veel regen in korte tijd kan tegelijk voor problemen zorgen. Ik hoef dus niet te kiezen tussen regen is goed en regen is slecht. De gevolgen hangen af van hoeveelheid, timing en de plek. We bekijken een neerslagkaart en lezen de legenda, zodat we niet iedere blauwe kleur zomaar als een rivier beschouwen."],"points":["arjun-mumbai","arjun-chennai"],"question":"Waarom kan regen tegelijk nuttig en lastig zijn?","options":["Water is nodig, maar veel regen in korte tijd kan overlast geven","Regen heeft op iedere plek altijd hetzelfde gevolg","Alle regen valt alleen in de hoofdstad"],"answer":0,"explanation":"De gevolgen hangen af van de hoeveelheid, timing, afvoer en de omgeving.","learn":"Leg verbanden tussen klimaat, water, landbouw en het dagelijks leven.","kind":"choice"},{"title":"Een kaartje van Chennai","paragraphs":["Mijn nicht in Chennai vertelt over haar schoolroute aan de andere kant van het land. Ik zoek haar stad aan de oostkust. Het is nog steeds India, maar mijn regenbui vertelt niet hoe het daar op hetzelfde moment is. Voor haar weer hebben we een lokale verwachting nodig. Voor klimaat vergelijken we gegevens over langere tijd. Ik stuur haar een tekening van onze speelplek. Zij stuurt er een van haar buurt terug. Zo leren we iets van elkaar zonder te doen alsof twee verhalen meteen het hele land beschrijven."],"points":["arjun-mumbai","arjun-chennai","in-cap"],"question":"Wat gebruik je om het weer van morgen in Chennai te weten?","options":["Een actuele lokale weersverwachting","Alleen Arjuns beschrijving van een bui in Mumbai","Alleen een kaart met de hoofdstad"],"answer":0,"explanation":"Het weer is plaats- en tijdgebonden. Een ervaring in Mumbai is geen verwachting voor Chennai.","learn":"Maak onderscheid tussen weer en klimaat en vergelijk meerdere plekken.","kind":"choice"}],"sources":[{"title":"India Meteorological Department · moesson","url":"https://mausamaudit.imd.gov.in/imd_latest/monsoonfaq.pdf"},{"title":"UNESCO · natuur en erfgoed bij dit verhaal","url":"https://whc.unesco.org/en/list/945/"}],"version":"fe84cc2e4643","memory_cue":"Mumbai: kuststad met spoorverbindingen en een station dat over koloniale geschiedenis vertelt.","insight":{"version":1,"question":"Waarom kun je een station ook als historische bron bekijken?","options":["De bouw en het gebruik vertellen over contacten, werk en bestuur in het verleden","Elk station is tegelijk de hoofdstad van het land","Een stationsgebouw vertelt alleen het weer van morgen"],"answer":0,"explanation":"Gebouwen hebben een ligging en een functie, maar bewaren ook sporen van historische verhoudingen."}},{"id":"sari","lesson":"world-asia","country":"id","child":"Sari","home":"Bandung","title":"Een eiland is nog geen heel land","bounds":[104,-9,116,-5],"places":[{"id":"sari-bandung","name":"Bandung","lon":107.61,"lat":-6.92,"kind":"city"},{"id":"id-cap","name":"Jakarta","lon":106.85,"lat":-6.21,"kind":"city"},{"id":"sari-bali","name":"Bali","lon":115.1,"lat":-8.4,"kind":"island"}],"scenes":[{"title":"Mijn straat in Bandung","paragraphs":["Ik ben Sari en ik woon in Bandung op Java. Voor een schoolopdracht teken ik onze omgeving. Er staan huizen en straten op, en in het landschap rondom de stad zijn bergen. Mijn broer wil er meteen heel Indonesië van maken. Daarvoor is mijn blad veel te klein. Bandung is een stad, Java een eiland en Indonesië het land met veel eilanden. Ik schrijf die drie niveaus onder elkaar. Dan kan iemand die mijn woonplek nog niet kent eerst het land en daarna mijn eiland en stad terugzoeken."],"points":["sari-bandung","id-cap"],"question":"Waar woont Sari?","options":["id-cap","sari-bandung"],"answer":"sari-bandung","explanation":"Sari woont in Bandung op het eiland Java.","learn":"Een land, eiland en stad zijn verschillende ruimtelijke niveaus.","kind":"map"},{"title":"Een bezoek binnen hetzelfde eiland","paragraphs":["Voor een bezoek aan familie in Jakarta bekijken we de verbinding vanaf Bandung. Beide steden liggen op Java. We kunnen daarom naar landverbindingen kijken, maar een rechte lijn door het landschap is nog geen weg of spoorlijn. Ik zoek ook de bergen op een hoogtekaart. Mijn moeder wil vooral weten welke echte verbinding bij ons plan past. Voor de precieze reistijd bekijken we actuele informatie. Mijn neef zegt dat hij me bij aankomst opwacht. Ik vraag of hij de route naar zijn huis alvast wil tekenen. Zo zie ik niet alleen waar zijn stad ligt, maar ook hoe ik de laatste straat kan vinden."],"points":["sari-bandung","id-cap"],"question":"Waarom bekijken Sari en haar moeder een echte vervoersverbinding?","options":["Een rechte kaartlijn volgt niet vanzelf wegen of spoor","Twee steden op hetzelfde eiland liggen altijd naast elkaar","Een hoogtekaart geeft alle vertrektijden"],"answer":0,"explanation":"Ligging, landschap en beschikbare verbindingen spelen samen een rol.","learn":"Gebruik een passende kaart én actuele vervoersinformatie bij een echt reisplan.","kind":"choice"},{"title":"Een kaartje van een ander eiland","paragraphs":["Een vriendin laat een kaartje van Bali zien. Ik wijs eerst naar Java, maar zij schudt haar hoofd. Bali is een ander eiland. Dat betekent dat een reis daarheen ook een oversteek vraagt. We bedenken welke soorten vervoer mogelijk zijn, zonder meteen te doen alsof elke route hetzelfde is. Op onze grote kaart tekenen we verschillende eilanden. Mijn vriendin vertelt over haar eigen ervaring; ik over die van mij. Het is fijn dat onze verhalen verschillen. Een land met zoveel eilanden kun je niet met één plaatje of één gewone schooldag samenvatten.","Mijn neef laat een foto zien van de Borobudur, een grote boeddhistische tempel op Java uit de achtste en negende eeuw. “Staat die dan in mijn straat in Bandung?” vraagt mijn vriend. Nee, hetzelfde eiland betekent nog niet dichtbij! Het bouwwerk laat bovendien zien dat Indonesië een lange en veelzijdige religieuze geschiedenis heeft. Eén tempel vertelt niet wat alle inwoners nu geloven. Ik zet een klein tempeltje bij Java en houd daarnaast ruimte voor de steden en andere eilanden van nu."],"points":["sari-bandung","id-cap","sari-bali"],"question":"Welk kaartanker hoort bij een ander eiland dan Java?","options":["sari-bandung","id-cap","sari-bali"],"answer":"sari-bali","explanation":"Bali is een ander eiland. Bandung en Jakarta liggen op Java.","learn":"Een archipel is een eilandengroep. Water en landverbindingen beïnvloeden hoe mensen reizen.","kind":"map"}],"sources":[{"title":"Indonesia Travel · West-Java en Bandung","url":"https://www.indonesia.travel/gb/en/destination/java/west-java"},{"title":"UNESCO · natuur en erfgoed bij dit verhaal","url":"https://whc.unesco.org/en/list/592/"}],"version":"cf1c7380e30f","memory_cue":"Indonesië: veel eilanden; op Java liggen Bandung én eeuwenoud erfgoed zoals de Borobudur.","insight":{"version":1,"question":"Wat mag je uit één foto van de Borobudur concluderen?","options":["Op Java is belangrijk boeddhistisch erfgoed, maar niet iedereen hoeft hetzelfde te geloven","Alle Indonesiërs hebben noodzakelijk hetzelfde geloof","Alle plaatsen op Java liggen op loopafstand"],"answer":0,"explanation":"Erfgoed laat een deel van de geschiedenis zien. Het bewijst niet hoe alle huidige inwoners leven of geloven."}},{"id":"yasmine","lesson":"world-africa","country":"ma","child":"Yasmine","home":"Marrakech","title":"Mijn stad en de bergen verderop","bounds":[-11,28,-2,36],"places":[{"id":"yasmine-marrakech","name":"Marrakech","lon":-7.98,"lat":31.63,"kind":"city"},{"id":"yasmine-rabat","name":"Rabat","lon":-6.84,"lat":34.02,"kind":"city"},{"id":"yasmine-atlas","name":"Hoge Atlas bij Marrakech","lon":-7.8,"lat":31.1,"kind":"area"}],"scenes":[{"title":"Een omweg met mijn vriendin","paragraphs":["Ik ben Yasmine en ik woon in Marrakech. Op weg naar een afspraak wil mijn vriendin nog even langs een bekende plek. Ik kijk of we dan niet te laat komen. Onze eigen buurtkaart heeft straten en herkenningspunten. Een kaart van heel Marokko is daarvoor veel te grof. Op die grotere kaart zoek ik wel de stad waar ik woon. Daarna zet ik Rabat erbij, de hoofdstad aan de Atlantische kust. Marrakech ligt verder in het binnenland. Het is handig dat een stad een naam heeft, maar voor mijn gewone looproute heb ik veel meer details nodig.","In de medina, het oude stadsdeel van Marrakech, kijken we naar muren en poorten. De stad bestaat al sinds de elfde eeuw en was lang een belangrijk centrum voor handel, bestuur en cultuur. Ik onthoud mijn stad in het binnenland met een oude poort en bergen verderop. Maar een oude wijk is geen museum waar niemand woont: mensen hebben er ook nu huizen en werk. Als er meer bezoekers komen, moet je dus niet alleen aan foto’s denken, maar ook aan de ruimte voor bewoners."],"points":["yasmine-marrakech","yasmine-rabat"],"question":"Waar woont Yasmine?","options":["yasmine-marrakech","yasmine-rabat"],"answer":"yasmine-marrakech","explanation":"Yasmine woont in Marrakech. Rabat is de hoofdstad van Marokko.","learn":"Gebruik een kaart die past bij de schaal van je vraag.","kind":"map"},{"title":"De bergen zijn geen stadsrand op papier","paragraphs":["Bij een uitstap kijken we richting de Hoge Atlas. De bergen maken mijn tekening heel anders dan een tekening van onze straat. Op een hoogtekaart zoek ik eerst de legenda. Een bruine kleur betekent hier hoogte, niet dat iedere plek dezelfde grondkleur heeft. Ik wil weten hoe hellingen invloed hebben op waar wegen en dorpen liggen. Een rechte lijn op de kaart kan in de bergen een lastige route zijn. Mijn broer tekent een tunnel waar hij de berg niet wil overtekenen. In het echt kun je die natuurlijk niet zomaar bijverzinnen."],"points":["yasmine-marrakech","yasmine-atlas"],"question":"Welke extra kaart helpt om de invloed van hellingen op routes te onderzoeken?","options":["Een hoogtekaart met legenda","Alleen een lijst met stadsnamen","Alleen een kaart met de landsgrens"],"answer":0,"explanation":"Een hoogtekaart laat verschillen in reliëf zien.","learn":"Reliëf beïnvloedt mogelijkheden voor wonen en vervoer.","kind":"choice"},{"title":"Een stad aan zee en een stad landinwaarts","paragraphs":["Een familielid in Rabat stuurt een foto van de kust. Ik zet die naast mijn eigen stadsfoto en een beeld van de bergen. Alle drie horen bij Marokko, maar ze laten verschillende omgevingen zien. Ik schrijf bij ieder beeld de plaats en wat ik nog wil onderzoeken. Een foto van een warme middag vertelt bijvoorbeeld niet het klimaat van het hele land. Daarvoor hebben we gegevens over langere tijd en meerdere plekken nodig. Mijn vriendin wil haar eigen favoriete plek toevoegen. Dat mag: onze ervaringen maken de kaart persoonlijker, zonder dat ze voor iedereen hetzelfde hoeven te zijn."],"points":["yasmine-marrakech","yasmine-rabat"],"question":"Welke stad uit het verhaal ligt aan de Atlantische kust?","options":["yasmine-marrakech","yasmine-rabat"],"answer":"yasmine-rabat","explanation":"Rabat ligt aan de Atlantische kust. Marrakech ligt landinwaarts.","learn":"Vergelijk kust, binnenland en gebergte. Eén beeld toont niet alle landschappen van een land.","kind":"map"}],"sources":[{"title":"UNESCO · Rabat","url":"https://whc.unesco.org/en/list/1401/"},{"title":"Marokkaans Nationaal Verkeersbureau · Marrakech","url":"https://visitmorocco.com/en/destinations/marrakech"},{"title":"UNESCO · natuur en erfgoed bij dit verhaal","url":"https://whc.unesco.org/en/list/331/"}],"version":"ba234006e8a0","memory_cue":"Marrakech: oude stad in het binnenland, met handel en de Atlas als herkenningspunt.","insight":{"version":1,"question":"Waarom hebben bewoners een belang bij plannen voor de medina?","options":["Het is erfgoed én een plek waar mensen wonen en werken","In oude stadsdelen wonen per definitie geen mensen","Een mooie foto maakt alle belangen gelijk"],"answer":0,"explanation":"Dezelfde ruimte heeft historische waarde en dagelijkse functies. Daarom kunnen belangen verschillen."}},{"id":"deniz","lesson":"eu-oost","country":"tr","child":"Deniz","home":"Istanbul","title":"Met de boot naar een ander werelddeel","bounds":[26,37,34,42],"places":[{"id":"deniz-istanbul","name":"Istanbul","lon":28.98,"lat":41.01,"kind":"city"},{"id":"tr-cap","name":"Ankara","lon":32.86,"lat":39.93,"kind":"city"},{"id":"deniz-bosphorus","name":"Bosporus","lon":29.05,"lat":41.1,"kind":"water"}],"scenes":[{"title":"Een gewone oversteek met een bijzondere naam","paragraphs":["Ik ben Deniz en ik woon in Istanbul. Als we de veerboot nemen, kijk ik graag naar de andere schepen. Soms voelt een tocht over het water voor mij gewoner dan een lange rit door de straten. Op een kaart ontdek je iets bijzonders: de Bosporus loopt tussen het Europese en Aziatische deel van de stad. Met een oversteek kun je dus van het ene werelddeel naar het andere gaan, terwijl je in dezelfde stad blijft. Mijn vriend wil daarvoor twee landenvlaggen tekenen, maar dat klopt niet. Beide delen horen bij Turkije."],"points":["deniz-istanbul","deniz-bosphorus"],"question":"Wat klopt over de twee kanten van Istanbul?","options":["De stad heeft een Europees en een Aziatisch deel binnen Turkije","Elke oever is een ander land","De Bosporus is een landsgrens tussen Turkije en Nederland"],"answer":0,"explanation":"De Bosporus scheidt de Europese en Aziatische stadsdelen; beide liggen in Turkije.","learn":"Een grens tussen werelddelen is niet automatisch een landsgrens.","kind":"choice"},{"title":"De hoofdstad ligt ergens anders","paragraphs":["Een klasgenoot denkt dat Istanbul de hoofdstad is. Het is een bekende grote stad, dus ik snap de vergissing. Toch zoeken we Ankara op. Dat is de hoofdstad van Turkije en ligt in het binnenland. Ik zet beide plaatsen op de kaart en vergelijk de ligging. Voor een bezoek aan familie bij Ankara moeten we een echte reis plannen. De veerboot in mijn eigen stad is niet ineens een verbinding naar elke andere plaats. We kijken naar wegen of spoor, en voor tijden naar actuele informatie. Dan wordt duidelijk waarom alleen twee stippen niet het hele reisplan vertellen."],"points":["deniz-istanbul","tr-cap"],"question":"Welke stad is de hoofdstad van Turkije?","options":["deniz-istanbul","tr-cap"],"answer":"tr-cap","explanation":"Ankara is de hoofdstad. Istanbul is een andere grote stad.","learn":"Een hoofdstad hoeft niet de bekendste of grootste stad te zijn.","kind":"map"},{"title":"Wie moet er langs?","paragraphs":["Bij de waterkant zie ik grote schepen, kleinere boten en mensen die naar hun afspraak willen. Ze gebruiken allemaal dezelfde omgeving, maar niet voor hetzelfde doel. Voor een werkstuk teken ik welke verbinding voor wie belangrijk is. Ik voeg geen verzonnen vaartijden toe: daarvoor zouden we de juiste actuele bron moeten lezen. Mijn eigen verhaal begint bij het uitzicht dat ik graag zie. De aardrijkskundige vraag erachter wordt groter: hoe zorgen water, stad en verbindingen samen voor de manier waarop mensen zich verplaatsen? Dat vind ik een mooie vraag om met de klas te onderzoeken.","Aan de waterkant denk ik aan de vele eeuwen waarin Istanbul een belangrijke stad was voor handel en bestuur. Gebouwen zoals de Hagia Sophia vertellen over verschillende tijden en gebruiken. De ligging bij de Bosporus maakte de plek belangrijk voor verbindingen tussen gebieden. Mijn tekening wordt een boot tussen twee oevers met een oud gebouw erbij. Zo onthoud ik tegelijk de ligging en waarom mensen juist hier samenkwamen. De hoofdstad van Turkije is nu Ankara; een belangrijke historische stad hoeft niet de huidige hoofdstad te zijn."],"points":["deniz-istanbul","deniz-bosphorus","tr-cap"],"question":"Welke vraag onderzoekt een verband tussen mens en ruimte?","options":["Hoe beïnvloedt de waterweg de routes van bewoners en schepen?","Hoe spel je alleen de naam van de hoofdstad?","Hoeveel letters staan er op het plaatsnaambord?"],"answer":0,"explanation":"De vraag verbindt water, vervoer en gebruik van de omgeving.","learn":"Onderzoek hoe verschillende gebruikers dezelfde ruimte nodig hebben.","kind":"choice"}],"sources":[{"title":"Turks ministerie van Cultuur en Toerisme · Istanbul en omgeving","url":"https://www.ktb.gov.tr/EN-99333/istanbul-and-surroundings.html"},{"title":"UNESCO · natuur en erfgoed bij dit verhaal","url":"https://whc.unesco.org/en/list/356/"}],"version":"8970097e0f0f","memory_cue":"Istanbul: Bosporus, twee werelddelen en lange handelsgeschiedenis; hoofdstad: Ankara.","insight":{"version":1,"question":"Welk verband maakt Istanbul aardrijkskundig en historisch interessant?","options":["De waterverbinding beïnvloedde handel en het belang van de stad","Een belangrijke handelsstad is altijd de huidige hoofdstad","Historische gebouwen maken de kaartligging overbodig"],"answer":0,"explanation":"Ligging helpt historische verbindingen begrijpen. Het belang van Istanbul verandert niet dat Ankara de huidige hoofdstad is."}}];
